// Üretilen dosya: tool/ozgun/uret.py. Doğa · Doğa gözlemi, mevsimler, iz sürme ve doğada güvenlik (orta).
const ozNature14Orta = <(String, String, List<String>, String)>[
  ('40° kuzey enleminde bir gözlemci 21 Haziran öğle vakti Güneş\'in ufuk çizgisinden yüksekliğini ölçüyor. Eksen eğikliği 23,5° alınırsa ölçüm yaklaşık kaç derece çıkar?', '73,5°', ['50°', '26,5°', '63,5°'], 'Öğle yüksekliği = 90° − enlem + güneşin deklinasyonu = 90 − 40 + 23,5 = 73,5° bulunur. Kış gündönümünde aynı değer 90 − 40 − 23,5 = 26,5° olurdu.'),
  ('Bir öğrenci okul bahçesine dikey bir çubuk dikip her ay aynı günde öğle gölgesinin uzunluğunu ölçüyor. Kuzey Yarımküre\'de gölge en uzun hangi tarihe yakın ölçülür?', '21 Aralık', ['21 Haziran', '21 Mart', 'Eylül ayının başı'], 'Kış gündönümünde Güneş öğle vakti yılın en alçak konumundadır; bu yüzden dikey bir cismin gölgesi yılın en uzun hâlini alır.'),
  ('Dünya\'nın dönme ekseni yörünge düzlemine tam dik olsaydı Türkiye\'de yaşam nasıl değişirdi?', 'Gün uzunluğu ve Güneş yüksekliği yıl boyu aynı kalır, belirgin mevsimler oluşmazdı', ['Yaz mevsimi çok daha uzun, kış mevsimi ise çok daha kısa olur ve bu fark her yıl büyürdü', 'Bütün yıl boyunca kutup bölgelerinde gece, ekvatorda ise sürekli gündüz yaşanırdı', 'Yalnızca Güney Yarımküre\'de mevsimler görülür, Kuzey Yarımküre\'de iklim sabit kalırdı'], 'Mevsimler eğiklikten doğduğu için eğiklik sıfır olsa her enlemde Güneş yüksekliği ve gün uzunluğu yıl boyu sabit kalırdı.'),
  ('1 m uzunluğundaki dikey bir çubuğun gölgesi, Güneş ufuktan 30° yükseklikte iken yaklaşık kaç metredir?', '1,73 m', ['0,58 m', '1 metre', '2 metre'], 'Gölge uzunluğu = çubuk boyu / tan(Güneş yüksekliği) = 1 / tan 30° ≈ 1,73 m eder. Güneş 45° ise gölge boya eşit olurdu.'),
  ('Bir bahçıvan bir böceğin gelişimini tahmin etmek için "derece-gün" toplar. Taban sıcaklığı 10 °C alınırsa, en yüksek 24 °C ve en düşük 12 °C olan bir günün derece-gün değeri kaçtır?', '8 derece-gün', ['14 derece-gün', '18 derece-gün', '12 derece-gün'], 'Günlük ortalama (24+12)/2 = 18 °C\'dir; taban 10 °C çıkarılınca 8 derece-gün elde edilir. Bu değerler günler boyunca toplanarak gelişim evresi tahmin edilir.'),
  ('Bir araştırmacı ağaca zarar vermeden halka örneği almak için hangi aleti kullanır?', 'Artım burgusu', ['Odun testeresi', 'Kazma ve kürek', 'El baltası'], 'Artım burgusu, gövdeye yatay sokulan içi boş bir burgudur; ince bir odun silindiri çıkarılarak halkalar sayılır, ağaç ölmez.'),
  ('Bir gölün donmuş yüzeyinde berrak, mavimsi buz ile kar karışımı beyaz, mat buz görülürse hangisi için hangi yorum yapılır?', 'Berrak mavimsi buz daha sağlamdır, beyaz mat buz daha zayıftır', ['Beyaz mat buz her zaman daha sağlamdır; berrak mavi buz ise kırılgan ve çatlamaya yatkındır', 'Buzun rengiyle sağlamlığı arasında hiçbir ilişki yoktur, kalınlık da önemsizdir', 'İkisi de aynı yükü taşır, çünkü buz her zaman aynı kristal yapıda donar'], 'Berrak buz yavaş ve saf donmuştur, hava kabarcıklı beyaz buz ise kar ve su karışımından oluştuğu için çok daha zayıftır; yine de buza güvenmek riskli olabilir.'),
  ('Büyükayı\'nın kepçe kısmındaki "işaretçi" iki yıldız (Dubhe ve Merak) kullanılarak Kutup Yıldızı nasıl bulunur?', 'Aralarındaki uzaklığın yaklaşık beş katı kadar uzatılır', ['Kepçenin ağzındaki bu iki yıldızın tam ortasından kepçe tabanına doğru dikine inilir', 'Kepçenin sapının ucundaki yıldızdan batıya doğru ilerleyen bir doğru takip edilir', 'Kepçenin tabanından doğuya doğru iki kat uzaklıkla ilerlenerek bir noktaya varılır'], 'Kepçenin ağzındaki bu iki yıldızdan geçen hayali doğru, uzaklıklarının yaklaşık beş katı kadar uzatılınca Küçükayı\'nın kuyruk ucundaki Kutup Yıldızı\'na varır.'),
  ('Ankara yaklaşık 40° kuzey enlemindedir. Ankara\'da bir gözlemci Kutup Yıldızı\'nın kuzey ufkunun üzerindeki yüksekliğini ölçerse sonuç yaklaşık kaç derece çıkar?', '40°', ['50°', '90°', '23,5°'], 'Kutup Yıldızı gök kutbuna çok yakındır ve kuzey ufkundan yüksekliği gözlemcinin enlem derecesine eşittir; bu yüzden denizciler bu yöntemle enlemi bulur.'),
  ('Bir gözlemci sabit bir noktadan dört saat boyunca Kuzey Yarımküre\'de yıldızların hareketini kaydediyor. Kutup Yıldızı çevresindeki yıldızlar ne kadar açı katetmiş olur?', 'Saat yönünün tersine yaklaşık 60°', ['Saat yönünde yaklaşık 60°', 'Saat yönünün tersine yaklaşık 120°', 'Saat yönünde yaklaşık 30°'], 'Dünya\'nın dönmesi, yıldızları günde 360° yani saatte 15° kaydırır. Kutup Yıldızı\'na bakıldığında dönüş saat yönünün tersinedir; dört saatte 4 × 15 = 60° eder.'),
  ('Venüs neden gece yarısı gökyüzünde görülemez?', 'İç gezegen olduğundan Güneş\'ten en çok 47° uzaklaşır', ['Venüs gece yarısı Ay\'ın arkasına saklandığı için ancak gündüz teleskopla seçilebilir', 'Venüs\'ün yüzeyi geceleri karanlıklaştığından yansıttığı ışık sıfıra yaklaşır', 'Venüs yalnızca kışın görünür, yazın ise Güneş\'in ötesinde kalır ve hiç görünmez'], 'Yörüngesi Dünya\'nın içinde olan Venüs, gökte Güneş\'ten belirli bir açıdan fazla ayrılamaz; bu yüzden ya akşam ya sabah yıldızı olarak Güneş\'in yakınında görünür.'),
  ('Kuzey Yarımküre\'de bir akşam batı ufkunda sağ tarafı aydınlık ince bir hilal görülüyor. Ay hangi evrededir?', 'Büyüyen hilal (yeni aydan sonra)', ['Küçülen hilal (son dördün sonrası)', 'Şişkin ay (dolunaya yakın evre)', 'Son dördün evresi'], 'Kuzey Yarımküre\'de büyüyen Ay\'ın sağ tarafı, küçülen Ay\'ın sol tarafı aydınlık görünür; akşam batıda görülen ince hilal yeni aydan birkaç gün sonrasındadır.'),
  ('İnce bir hilal sırasında Ay\'ın karanlık kısmının soluk gri biçimde seçilebilmesinin nedeni nedir?', 'Dünya\'dan yansıyan ışığın Ay\'ı hafifçe aydınlatması', ['Ay\'ın kendi ışık yayması', 'Yıldız ışığının Ay\'a çarpması', 'Atmosferdeki parlayan gazlar'], 'Bu olaya kül ışığı denir; Dünya\'nın bulutları ve okyanusları Güneş ışığını Ay\'a yansıtır ve karanlık yüz çok soluk bir ışıkla görünür.'),
  ('Gökyüzünde zayıf nesneleri (Samanyolu, bulutsular) görmek isteyen amatör gözlemci hangi koşulları seçmelidir?', 'Yeni ay dönemi, ışık kirliliğinden uzak, açık ve nemsiz bir gece', ['Dolunaylı, şehir ışıklarının güçlü olduğu ve yer yer sisli bir gece', 'Yağmurun hemen dindiği, bulutların hâlâ dağılmadığı ve nemin çok yüksek olduğu bir gece', 'Sisli, ılık ve rüzgârsız, atmosferde nemin çok yüksek olduğu bir yaz gecesi'], 'Ay ışığı ve şehir aydınlatması gökyüzü arka planını parlatıp soluk nesneleri gizler; karanlık, kuru ve açık göğe ihtiyaç vardır.'),
  ('Karanlık gözlem alanına ilk çıkan bir kişi gözlerinin geceye tam uyum sağlaması için yaklaşık ne kadar beklemelidir?', '20–30 dakika', ['1–2 dakika', '5 saniye kadar', 'Yaklaşık 3 saat'], 'Gözün retinasındaki çubuk hücreler zayıf ışığa tam duyarlılığa 20–30 dakikada ulaşır; bu sürede parlak ışığa bakılırsa uyum bozulur.'),
  ('Bir kamp alanında akşam analog kol saatiyle yön bulmak isteyen biri saatin akrebini Güneş\'e çeviriyor. Kuzey Yarımküre\'de güney yönü nasıl bulunur?', 'Akrep ile saat 12 işareti arasındaki açının açıortayı güneyi gösterir', ['Akrebin tam arkasındaki doğrultu güneyi gösterir, yelkovan ise kuzeyi belirler', 'Saatin yelkovanı güneşe çevrilir ve yelkovanın ucu doğrudan güneyi gösterir', '12 işareti Güneş\'e çevrildiğinde 12 işaretinin gösterdiği doğrultu güney olur'], 'Güneş saatte 15° döner, akrep ise 30° döndüğünden, akrep ile 12 arasındaki açının ortası güney yönünü verir; yöntem yaklaşık bir sonuç sunar.'),
  ('Yön bulmak için yere dikilen çubuğun gölge ucu işaretleniyor ve yaklaşık 20 dakika sonra yeniden işaretleniyor. İlk işaretten ikinciye çizilen doğrunun yönü neyi gösterir?', 'Yaklaşık batıdan doğuya doğrultuyu', ['Yaklaşık kuzeyden güneye doğrultuyu', 'Ayın yönünü', 'Rüzgâr yönünü'], 'Gölge Güneş\'in tersine, yani batıdan doğuya hareket eder; ilk işaret batı, ikinci işaret doğu tarafında kalır ve doğru doğu-batı çizgisini verir.'),
  ('"Ağaçlarda yosun hep kuzey tarafındadır" kuralı için ne söylenebilir?', 'Güvenilmezdir; yosun nemli ve gölgeli yöne yerleşir, bu yön yere göre değişebilir', ['Her yerde ve her koşulda kesin doğrudur; yosun daima ağacın kuzey yüzünde gelişir', 'Yalnızca ekvatorda doğrudur, çünkü orada Güneş her gün tam tepeden gelir', 'Yalnızca çam ağaçlarında doğrudur, çünkü kozalaklı ağaçların kabuğu yosuna uygundur'], 'Yosun gölge ve nem arayan canlı olduğundan hâkim rüzgâr, orman yoğunluğu ve yamaç eğimi onun yönünü değiştirir; tek başına güvenilir bir pusula değildir.'),
  ('Bir yürüyüşçü 70° azimutla ilerledikten sonra başladığı yere dönmek istiyor. Hangi azimuta yönelmelidir?', '250°', ['110°', '290° azimutla', '20 derece'], 'Geri azimut, 180° eklenerek (ya da 180° azimut 180°\'den büyükse çıkarılarak) bulunur: 70 + 180 = 250°.'),
  ('Manyetik sapma 6° doğuda olan bir bölgede, haritadan ölçülen gerçek azimut 90° ise pusulada kaç derece okunmalıdır?', '84°', ['96°', '90°', '180°'], 'Manyetik kuzey gerçek kuzeyin doğusunda ise, gerçek azimut değerinden sapma çıkarılır: 90 − 6 = 84°. Batı sapmada ise sapma eklenir.'),
  ('Haritada eş yükselti eğrileri, ucu yüksek yöne bakan V biçimleri çiziyorsa bu arazi biçimi hangisidir?', 'Vadi (dere yatağı)', ['Sırt hattı (su ayrım çizgisi)', 'Tepe zirvesi (yüksek nokta)', 'Geniş düzlük alan'], 'Dere vadisinde eğriler yukarıya, yani yüksek yöne doğru V biçiminde kıvrılır; sırtta ise eğrilerin uçları alçak yöne bakar.'),
  ('Eş yükselti eğrileri arasında 10 m aralık olan bir haritada iki nokta arası yatayda 500 m, eğri sayısı farkı 5 ise ortalama eğim yüzde kaçtır?', '%10', ['%1 eğim', '%5 eğim', '%50 eğim'], 'Yükselti farkı 5 × 10 = 50 m\'dir; eğim = 50 / 500 = 0,10 yani %10 eder.'),
  ('8x42 dürbünün çıkış göz bebeği çapı (objektif çapı ÷ büyütme) kaç milimetredir?', '5,25 mm', ['0,19 mm', '3,36 mm', '12,25 mm'], 'Çıkış göz bebeği = 42 / 8 = 5,25 mm bulunur. Alacakaranlıkta insan gözbebeği yaklaşık bu çapa açılır, dolayısıyla bu dürbün loş ışıkta verimli çalışır.'),
  ('Dürbünde sol ve sağ göz arasında netlik farkı olduğunda hangi ayar bu farkı gidermek için kullanılır?', 'Diyoptri ayarı', ['Göz bebeği aralığı ayarı', 'Askı kayışı ayarı', 'Gün ışığı filtresi'], 'Önce bir göz ayrı, diğer göz ayrı odaklanır, diyoptri halkasıyla iki gözün keskinlik farkı dengelenir; sonra tek odak tekerleği iki göz için yeterli olur.'),
  ('Gözlük takan bir doğa gözlemcisi dürbün seçerken özellikle hangi teknik özelliğe bakmalıdır?', 'Göz mesafesi (eye relief) yeterince uzun olmalıdır', ['Dürbünün gövdesi mümkün olduğunca koyu renkli ve parlamayan malzemeden yapılmalıdır', 'Dürbünün ağırlığı hiç önemli değildir, çünkü uzun süre taşınmaz', 'Objektif çapı mümkün olduğunca küçük olmalıdır ki göz yorulmasın'], 'Göz mesafesi, göz merceğinden gözün görüntünün tamamını görebildiği uzaklıktır; gözlük takanlarda 15 mm ve üzeri tercih edilir.'),
  ('Bir öğrenci ışığın fasulye fidelerinin boyuna etkisini inceliyor: bir sınıf penceresinin önüne, diğerini karanlık dolaba koyuyor, ikisini de aynı miktarda suluyor ve boylarını ölçüyor. Bu deneyde bağımsız değişken hangisidir?', 'Işık miktarı', ['Fidenin boyu', 'Sulama miktarı', 'Saksı sayısı'], 'Araştırmacının bilerek değiştirdiği etken bağımsız değişkendir; ölçülen sonuç (boy) bağımlı, sabit tutulan sulama ise kontrol edilen değişkendir.'),
  ('Bir bahçedeki bitki yoğunluğunu tahmin etmek için 1 m² boyutunda 10 kuadrat atılıyor ve toplam 45 bitki sayılıyor. Alan 2000 m² ise toplam bitki sayısı yaklaşık kaç olarak tahmin edilir?', '9 000 bitki', ['4 500 bitki yaklaşık', '450 bitki yaklaşık', '900 bitki yaklaşık'], 'Kuadrat başına ortalama 45/10 = 4,5 bitki/m²\'dir; 2000 m² alan için 4,5 × 2000 = 9000 bitki bulunur.'),
  ('Bir göldeki balık sayısını tahmin etmek için 50 balık işaretlenip bırakılıyor. Daha sonra yakalanan 40 balığın 5\'i işaretli ise göldeki toplam balık sayısı yaklaşık kaçtır?', '400 balık', ['250 balık kadar', '100 balık kadar', '50 balık kadar'], 'Lincoln-Petersen yöntemine göre N = (işaretlenen × ikinci örnek) / ikinci örnekteki işaretli = 50 × 40 / 5 = 400 bulunur.'),
  ('Kıyıdan iç kesime doğru bitki örtüsünün nasıl değiştiğini incelemek için hangi örnekleme yöntemi en uygun olur?', 'Transekt', ['Rastgele atılan tek bir kuadrat ile bütün kıyıyı temsil etmek', 'Yalnızca uzaktan fotoğraf çekip bitkileri sayıya dökmeden bırakmak', 'Bitkileri toplayıp laboratuvarda kurutarak ağırlıklarını karşılaştırmak'], 'Transekt, çevresel bir gradyan boyunca belirli aralıklarla örnek alımını sağlayarak türlerin yer değiştirmesini gözlemeyi kolaylaştırır.'),
  ('Çamurda dört parmak izi ve her parmağın önünde belirgin tırnak izleri bulunan yuvarlak-oval bir pati izi görülüyor. Bu iz hangi hayvan grubuna daha olasıdır?', 'Köpekgillere (tilki, kurt gibi)', ['Kedigillere (vaşak, yaban kedisi gibi)', 'Tavşangillere (yabani tavşan gibi)', 'Kemirgenlere (sincap, fare gibi)'], 'Köpekgillerin tırnakları geri çekilmez, bu yüzden izde parmakların önünde tırnak izi görülür; kedigil tırnakları çekilebildiğinden çoğu izde tırnak izi bulunmaz.'),
  ('Bir iz sürücü iz ayrıntılarını daha net görmek için hangi ışık koşulunu seçmelidir?', 'Güneş alçakken yandan gelen ışık', ['Öğle vakti tepeden gelen ışık', 'Tam karanlıkta el feneriyle arkadan aydınlatma', 'Güneşi tam karşıya alıp bakmak'], 'Alçak açıdan gelen yan ışık izin kenar ve çukurlarında gölge oluşturur, böylece derinlik ve parmak detayları belirgin görünür.'),
  ('Bir ayak izinin üzerine daha sonra yeni kar yağmışsa izin yaşı hakkında hangi çıkarım doğrudur?', 'İz, kar yağışından önce bırakılmıştır', ['İz, kar yağışından sonra bırakılmıştır', 'İz kar yağarken oluşmuştur', 'Kar izin yaşı hakkında bilgi vermez'], 'Yeni kar tabakası izi örtüyorsa, iz o kar yağmadan önce oluşmuş demektir; ne kadar kar birikmişse iz o kadar eskidir.'),
  ('Güneşte kar eridikçe kardaki bir hayvan izi için ne olur?', 'İz kenarları erir, iz olduğundan büyük ve belirsiz görünür', ['İz küçülür ve kenarları keskinleşir, çünkü karın sıkışması izi sertleştirir', 'İz tamamen aynı kalır, çünkü kar eriyince izdeki kar tabakası yeniden donar', 'İz sürekli derinleşir ve şekli bozulmadan olduğu gibi korunur'], 'Erime nedeniyle kenarlar geriler ve izin gerçek boyutu abartılı görünür; bu yüzden iz boyutu için sabah, serin saatlerde ölçüm yapılmalıdır.'),
  ('Yumuşak çamur ya da ıslak kumdaki bir ayak izinin kalıbını almak için hangi madde yaygın olarak kullanılır?', 'Alçı (jips) sulu karışımı', ['Tuz ve su karışımı, çünkü kuruyunca sertleşip kalıp verir', 'Su bazlı boya, çünkü iz üzerine sürülünce kalıbı yapar', 'Balmumu ve sıvı yağ karışımı, çünkü çamurda katılaşır'], 'İz çevresine halka konarak içine dökülen alçı sertleşince izin kalıbı çıkarılır; böylece iz boyutları sonradan ölçülebilir.'),
  ('İnsan ayak izine benzeyen, beş parmak ve topuk izi bulunan geniş bir iz hangi hayvana ait olabilir?', 'Ayı', ['Kurt', 'Karaca', 'Vaşak'], 'Ayılar tabanlarının tamamıyla basan (plantigrad) hayvanlardır; iz geniştir, beş parmak ile uzun tırnak izleri ve topuk bölümü görülür.'),
  ('Yürüyüşte bir kozalağın pulları çıplak bir eksen kalacak biçimde ve kenarları düzensizce kemirilmiş bulunursa bu iz neyi düşündürür?', 'Sincap benzeri bir kemirgenin beslendiğini', ['Ayının kozalak yediğini ve pulları dışarı kustuğunu', 'Fırtınanın kozalağı koparıp parçaladığını', 'Yaprak döken ağaçların kozalak yapraklarını attığını'], 'Sincaplar kozalak pullarını sırayla koparıp çekirdeklere ulaşır; geriye çıplak eksen ve pul artıkları kalır, bu klasik bir beslenme izidir.'),
  ('Yaban hayvanı dışkılarını çıplak elle toplamak ve yabani meyveleri yıkamadan yemek neden önerilmez?', 'Dışkıyla bulaşan parazit yumurtaları (örneğin ekinokok) insanlara geçebilir', ['Dışkı zehirli gaz çıkarır ve çıplak elle dokunan kişiyi hemen zehirler', 'Meyveler dışkıyla temas edince zehirli hâle gelir ve insan sağlığına zarar verir', 'Dışkı çok sıcak olduğu için parmaklarda yanık oluşturur'], 'Tilki ve köpekgil dışkısındaki bazı parazit yumurtaları yere, bitkilere ve ele bulaşabilir; hijyen için eldiven kullanılır ve yabani meyveler yıkanır.'),
  ('Bir porsuk yuvasını arayan gözlemci için en güvenilir ipucu hangisidir?', 'Giriş önünde taze kazı toprağı ve yatak otları', ['Ağaç tepesinde sivri uçlu büyük bir dal yığını ve çevresinde kuş tüyleri', 'Dere kıyısındaki yosunlu bir taşın altında küçük bir mağara', 'Çalılık içinde yeşil kozalak ve kırılmış dallar bulunması'], 'Porsuklar toprakta çok odalı yuvalar kazar; girişlerin önünde atılan toprak yığını, kuru yatak otları ve patikalar yuvanın kullanıldığını gösterir.'),
  ('Alacakaranlıkta aynı su başına gelen hayvan izlerini incelemek isteyen biri en çok hangi yeri seçmelidir?', 'Su başındaki yumuşak çamurlu kıyı', ['Dağın dik ve kayalık, bitki örtüsü az yamacı', 'Taşlı, sert ve kuru bir kaya zemin', 'Yoğun çalı örtüsünün içindeki gölgeli bir bölge'], 'Nemli, ince taneli çamur ve kum, izlerin net ve kalıcı olmasını sağlar; hayvanlar su içmeye geldiği için su başları iz gözlemi açısından verimlidir.'),
  ('Bir yürüyüşçü, barometresinin birkaç saat içinde hızla düştüğünü görüyor. Bu gözlem hava durumu açısından neyi haber verir?', 'Alçak basınç ve cephenin yaklaştığını', ['Havanın kısa sürede açılıp güneşleneceğini ve basıncın yükseleceğini', 'Sıcaklığın gece boyunca hiç değişmeyeceğini ve yağış çıkmayacağını', 'Sisin dağılacağını ve rüzgârın tamamen duracağını'], 'Basıncın hızla düşmesi, alçak basınç merkezi ve cephe yaklaşırken görülür; bulutlanma, yağış ve rüzgâr artışı beklenir.'),
  ('Yaz öğleden sonrasında küçük beyaz kümülüs bulutlarının hızla yukarı büyüyüp koyu ve çok yüksek bir bulut hâlini aldığı görülüyor. Bir kampçı bu durumda ne yapmalıdır?', 'Açık alandan ve tepelerden uzaklaşıp korunak aramalıdır', ['Yürüyüşe zirve yönünde hız kesmeden devam edip zirveden manzarayı beklemelidir', 'Çadırını yüksek ve tek duran bir ağacın altına kurup oradan korunmalıdır', 'Gölün kıyısında su kenarında durup yağmurun geçmesini beklemelidir'], 'Hızla dikey gelişen kümülüs, sağanak ve yıldırım üreten bulutun habercisidir; yüksek tepeler ve tek ağaçlar riskli olduğundan güvenli bir yere çekilmelidir.'),
  ('Açık, rüzgârsız ve bulutsuz bir gecede sabaha doğru yer yüzeyi çevresine göre neden daha çok soğur?', 'Yer yüzeyi ısıyı ışınımla kaybeder, bulut örtüsü yoktur', ['Dolunay ışığı yeryüzünü soğutur, bu yüzden açık gecede sıcaklık düşer', 'Rüzgâr olmadığı için hava yoğunlaşır ve yer yüzeyi daha çok soğur', 'Gece Güneş\'in Dünya\'dan uzaklaşması nedeniyle ısı enerjisi tamamen yok olur'], 'Bulutsuz göğün altında yerden çıkan kızılötesi ışınım uzaya kaçar; bulut örtüsü olsaydı bu ısıyı tutup soğumayı azaltırdı.'),
  ('Ağaçların tümünün sallandığı, rüzgâra karşı yürümenin zorlaştığı bir günde rüzgâr yaklaşık hangi Beaufort kuvvetindedir?', '7', ['2', '4', '12'], 'Beaufort 7\'de (yaklaşık 50–61 km/s) büyük ağaçlar sallanır ve rüzgâra karşı yürümek güçleşir; 12 ise kasırga şiddetindedir.'),
  ('Bir gözlemci rüzgâr yönünü belirlemek için ıslattığı parmağını havaya kaldırıyor. Rüzgârın estiği taraf nasıl hissedilir?', 'Daha soğuk hissedilir', ['Daha sıcak hissedilir, çünkü rüzgâr ısıyı getirir', 'Aynı sıcaklıkta kalır, hiçbir fark olmaz', 'Daha ağır hissedilir'], 'Rüzgâr gelen yönde parmaktaki suyun buharlaşması hızlanır, o yüz serinler; rüzgârın estiği yön bu yüzden parmakta daha soğuk hissedilir.'),
  ('Bir kayalıkta Beaufort 8 şiddetinde fırtınada yürüyüş yapmayı planlayan biri hakkında ne söylenebilir?', 'Güvenli değil; dallar kırılır, denge bozulur', ['Rüzgârın serinletici etkisinden dolayı yürüyüş çok keyifli olur', 'Rüzgâr kayalıkta dalga etkisi yapmaz ve yürüyüşü kolaylaştırır', 'Hava çok sıcak olacağı için bol su taşınmalı, yürüyüş sürdürülmelidir'], 'Beaufort 8 (yaklaşık 62–74 km/s) fırtınasında yürümek çok zorlaşır, dallar kırılabilir, açık yüzeylerde savrulma riski olur.'),
  ('Yağış ölçerle 15 mm yağış ölçülen bir günde 200 m² çatıya düşen su yaklaşık kaç litredir? (1 mm yağış = 1 L/m²)', '3000', ['300', '30', '15000'], '15 mm yağış her m² için 15 litre demektir; 15 × 200 = 3000 litre su düşmüştür.'),
  ('Meteoroloji ölçümlerinde hava sıcaklığı için termometrenin konumu nasıl olmalıdır?', 'Gölgede, havalandırılan barınakta, yerden 1,25–2 m yukarıda', ['Doğrudan Güneş\'te, yere değecek biçimde ve beton zemin üzerinde', 'Beton duvarın dibinde, yerden yarım metre yükseklikte', 'Pencere önünde, doğrudan Güneş\'e bakar biçimde'], 'Doğrudan güneş ışığı ya da yüzey ısısı ölçümü bozar; standart ölçümde termometre havalandırmalı bir barınakta, yerden 1,25–2 m yukarıda tutulur.'),
  ('Aynı su buharı miktarını içeren bir hava kütlesi ısındığında bağıl nemi nasıl değişir?', 'Düşer, çünkü sıcak hava daha çok buhar taşır', ['Artar, çünkü hava ısındıkça nem içeriği yükselir', 'Değişmez, çünkü su buharı miktarı sabittir', 'Sıfırlanır, çünkü sıcak hava hiç su buharı taşıyamaz'], 'Bağıl nem, mevcut buharın aynı sıcaklıkta tutulabilecek en yüksek buhara oranıdır; sıcaklık artınca kapasite büyür ve oran azalır.'),
  ('Deniz seviyesinde 20 °C ölçülen bir yerden 2000 m yükseğe çıkıldığında, ortalama 6,5 °C/km düşüş varsayımıyla sıcaklık yaklaşık kaç °C olur?', '7', ['13', '0', '-6'], 'Sıcaklık düşüşü 2 km × 6,5 = 13 °C\'dir; 20 − 13 = 7 °C bulunur.'),
  ('Kara yağış ölçeri kurarken nereye yerleştirilmelidir?', 'Açık alanda, engellerden yükseklikleri kadar uzakta', ['Çatı kenarında, rüzgâra açık ve yağmur akışının toplandığı yerde', 'Büyük bir ağacın altında, yaprakların yağışı toplayacağı noktada', 'Bir duvarın hemen dibinde, yağışın duvardan aktığı yerde'], 'Bina ve ağaçlar yağışı keser ya da yönünü değiştirir; ölçüm doğru olsun diye ölçer engellerden en az yükseklikleri kadar uzakta, açık alana konur.'),
  ('Hafif hipotermi geçiren, titreyen ama bilinci açık bir kişiye uygulanacak en uygun ilk yardım hangisidir?', 'Islakları çıkarıp yalıtmak, sıcak tatlı içecek vermek', ['Alkollü sıcak bir içecek içirip kişiyi rahatlatmak, damarları genişleterek ısıtmak', 'Kolları ve bacakları kuvvetle ovarak dolaşımı hızlandırmak', 'Soğuk suyla yıkayıp sonra hızla kurulayarak kan dolaşımını canlandırmak'], 'Islak giysi ısı kaybettirir; kuru yalıtım ve sıcak şekerli içecek vücut ısısını artırır. Alkol damarları genişletip ısı kaybını hızlandırır, kuvvetli ovma ise dolaşıma zarar verebilir.'),
  ('Soğuk suya ani düşmek ne tür ilk tehlike yaratır?', 'Soğuk şoku: ani hızlı solunum ve nefes darlığı', ['Hemen uykuya dalma ve kas gevşemesi sonucu suya batma', 'Kemiklerin birkaç saniyede donarak hareketi engellemesi', 'Kan basıncının hızla sıfıra düşmesi ve bilincin kaybolması'], 'Soğuk suya girişte ilk dakikada refleks olarak aşırı hızlı solunum ve kalp hızı artışı olur; bu, boğulma riskini yükseltir. Hipotermi sonraki aşamadır.'),
  ('Eksi sıcaklıkta yürüyüşte parmak uçları beyaz, mum gibi ve duyusuz görünüyorsa bu durumda ne yapılmalıdır?', 'Ilık ortama alıp vücut ısısıyla yavaşça ısıtmak, ovmamak', ['Parmaklar karla güçlü biçimde ovularak ısıtılmalı, kan dolaşımı bu yolla canlandırılmalıdır', 'Parmaklar doğrudan ateşe ya da sıcak soba üzerine tutularak hızla ısıtılmalıdır', 'Hiçbir şey yapılmadan yürüyüşe devam edilip akşamı beklemelidir'], 'Donmuş dokular kar ile ovulursa zedelenir, doğrudan ateşte ise duyusuz olduğundan yanabilir; ılık ortam ve vücut ısısıyla yavaş ısıtma gerekir.'),
  ('Yaz sıcağında yürüyüş yapan bir kişi aşırı terleme, solgun nemli cilt, baş dönmesi ve mide bulantısı yaşıyor ancak bilinci açık. Bu kişiyi nasıl tedavi edersiniz?', 'Gölgeye alıp gevşetmek, sıvı vermek, serinletmek', ['Güneş altında bırakıp bol hareketle ve koşturarak terlemesini sağlamak', 'Sadece kahve içirip yürüyüşe devam etmesini sağlamak', 'Üzerine kalın bir battaniye örterek terlemeyi artırmaya çalışmak'], 'Bu tablo sıcak bitkinliğidir; serin yere almak, sıvı ve tuz dengesini yeniden sağlamak gerekir. Düzelmezse ya da bilinç bozulursa sıcak çarpması kabul edilip acil yardım istenmelidir.'),
  ('Sıcak çarpması şüphesi olan, bilinci bulanık bir kişiye acil yardım gelene kadar ne yapılmalıdır?', 'Gölgeye alıp ıslak bezlerle hızla soğutmak', ['Üstüne kalın giysi ve battaniye giydirip terlemesini beklemek', 'Kişiyi yürütmeye devam ederek soğuk hava akımı oluşturmasını sağlamak', 'Yalnızca kısa bir uyku yaptırıp iyileşmesini beklemek ve su vermemek'], 'Çekirdek ısıyı hızla düşürmek hayat kurtarır; gölge, ıslak örtü, vantilasyon ve damarların geçtiği bölgelere (boyun, koltuk altı) soğuk uygulama etkilidir.'),
  ('Bir kişi 6 saatlik sıcak havada bir yürüyüş planlıyor ve saatte yaklaşık yarım litre su içmesi gerektiğini hesaplıyor. Su ihtiyacı yaklaşık kaç litredir?', '3 litre', ['0,5 litre', '6 litre', '12 litre'], '0,5 L/saat × 6 saat = 3 litre eder; sıcak, tırmanış ve yoğun terlemede miktar artabilir ve yedek su alınmalıdır.'),
  ('Uzun, terli bir yürüyüş sırasında yalnızca çok miktarda saf su içmenin sakıncası nedir?', 'Kan sodyumu seyrelip hiponatremi gelişebilir', ['Su içmek yorgunluğu artırır ve mide boşluğunu doldurup yemeyi engeller', 'Saf su vücuda zararlı kimyasallar taşıdığı için zehirlidir', 'Saf su sindirimi hızlandırır, açlığı kapatır ve enerji girişini azaltır'], 'Aşırı terde tuz kaybedilir; sadece su içilirse kan sodyumu düşer, baş ağrısı, kusma ve nöbet görülebilir. Tuzlu atıştırmalıklar bu riski azaltır.'),
  ('Çölde ya da sıcakta yürüyüş yaparken en iyi zaman planı aşağıdakilerden hangisidir?', 'Erken ve akşam yürüyüp öğle dinlenmek', ['Tam öğle vakti hızlıca yürümek', 'Gece boyunca hiç ışıksız yürümek', 'Sadece öğleden sonra su içmeden ilerlemek'], 'En sıcak saatlerde dinlenmek enerji ve su kaybını azaltır; serin saatlerde hareket sıcak çarpması riskini düşürür.'),
  ('Sıcak havada kapalı bir arabada çocuk ya da evcil hayvan bırakmak tehlikelidir. Bunun nedeni nedir?', 'Araç içi dakikalar içinde aşırı ısınır', ['Araç içi her zaman dışarıdan soğuk kalır, çünkü cam ısıyı yansıtır', 'Hayvanlar ve çocuklar sıcağı yetişkinlerden daha iyi taşır, rahat eder', 'Cam aralık bırakılırsa araç içi dışarıdan hiç ısınmaz, tehlike kalmaz'], 'Güneş altındaki kapalı aracın iç sıcaklığı kısa sürede yükselir; küçük bedenler ısıyı daha çabuk kazandığından risk yüksektir.'),
  ('Kar üzerinde güneşli bir günde gözlük takılmadığında en çok hangi sorun yaşanabilir?', 'Kar körlüğü', ['Gözde kalıcı renk körlüğü', 'Gözlerin kuruması ve kirpiklerin donması', 'Gece görüş kaybı'], 'Taze kar morötesi ışığın büyük bölümünü yansıtır; korunmasız gözde kornea yanıkları saatler sonra ağrı, sulanma ve ışık hassasiyeti yapar.'),
  ('Bulutlu bir gökyüzü altında güneş yanığı riski için hangisi doğrudur?', 'Hafif bulutlar UV\'nin büyük bölümünü geçirir; yanık oluşabilir', ['Bulut varsa UV tamamen engellenir ve yanık oluşmaz, güneş kremine gerek kalmaz', 'Yalnız yağmur yağarken yanık oluşur, hafif bulutta oluşmaz', 'Bulutlu havada UV hiç bulunmaz, çünkü ışık yalnız görünür dalga boyundadır'], 'İnce ve parçalı bulutlar morötesi ışığın büyük kısmını geçirir; serin hava yanılgı yaratıp koruma ihmal edilir.'),
  ('Doğada bir yılan ısırığı durumunda aşağıdakilerden hangisi önerilen ilk yardım adımıdır?', 'Kişiyi hareketsiz tutup hemen 112\'yi aramak', ['Yaranın üzerini bıçakla kesip zehri ağızla emmek', 'Isırılan bölgenin üstünü sıkı bir turnikeyle bağlamak', 'Yarayı buzla kaplayıp ısırılan kişiyi yürüterek hastaneye götürmek'], 'Hareket zehrin yayılmasını hızlandırır; kesme, emme ve turnike doku hasarını artırır. Asıl tedavi hastanede, antivenomla yapılır, bu yüzden acil yardım çağrılır.'),
  ('Bir yılanı gören yürüyüşçünün izlemesi gereken en güvenli davranış hangisidir?', 'Yavaşça geri çekilip yılana yol vermek', ['Yılanı yakalayıp fotoğrafını çekmek için yaklaşmak', 'Yılanı sopayla uzaklaştırmaya çalışmak', 'Yılana arkanı dönüp koşarak uzaklaşmak'], 'Yılanların çoğu insanlarla karşılaşmak istemez ve kaçar; yılana dokunmaya ya da onu hareket ettirmeye çalışanlar ısırık olaylarının önemli bir bölümünü oluşturur.'),
  ('"Başı üçgen olan her yılan zehirlidir" kuralı için ne söylenebilir?', 'Güvenilmez; bazı zararsız yılanlar da başını yassılaştırır', ['Her zaman doğrudur', 'Yalnız su yılanlarında geçerlidir', 'Yalnız kış aylarında doğrudur'], 'Baş şekli türü güvenilir biçimde ayırmaz; zararsız bazı yılanlar korktuğunda yapıyı yassılaştırır. Şüpheli durumda yılana yaklaşılmaz.'),
  ('Yürüyüşçülerin yılan ısırığı riskini azaltmak için aşağıdakilerden hangisini yapmaları önerilir?', 'Bot ve uzun pantolon giymek', ['Çıplak ayakla yürümek', 'Çalılıkların içinden gözü kapalı geçmek', 'Gece yerde yatarak dinlenmek'], 'Yılanlar genellikle saklandığı yerde ısırır; kalın bot ve pantolon kaza riskini azaltır, el ve ayakları görmediğiniz yere sokmamak en önemli önlemdir.'),
  ('Çadır kampında sabah ayakkabıları giymeden önce ters çevirip silkelemek neden önerilir?', 'İçine akrep ya da örümcek girmiş olabileceği için', ['Ayakkabılar ıslak kalır diye', 'Ayakkabıların rengi solmasın diye', 'Ayakkabı bağları dolanmasın diye'], 'Gece boyunca ayakkabı içi serin ve karanlık bir sığınak sunar; sallamak küçük hayvanları sokma riski doğmadan dışarı çıkarır.'),
  ('Bir arı soktuktan sonra derideki iğnenin çıkarılması nasıl yapılmalıdır?', 'Kart kenarı gibi sert bir kenarla kazıyarak', ['Ağızla emerek', 'Bölgeyi bastırarak ovarak', 'Yağ sürüp beklemeyerek'], 'Zehir kesesi iğneye bağlıdır; iğneyi mümkün olan en kısa sürede çıkarmak önemlidir. Kazıyarak çıkarmak çabuk ve pratik bir yöntemdir.'),
  ('Vücudunda kene bulan bir kişi keneyi nasıl çıkarmalıdır?', 'Cımbızla deriden düz çekmek', ['Keneyi yağ ya da benzinle boğarak', 'Keneyi sigara ateşiyle yakarak', 'Keneyi parmakla ezerek'], 'Kenenin gövdesini sıkmak ya da ezmek, içeriğini deriye geri iterek enfeksiyon riskini artırır; deriye yakın tutup çekmek ağız parçalarının kalmasını azaltır.'),
  ('Kene bölgelerinde yürüyüş yapan biri kenelerden korunmak için hangi giyim önlemini almalıdır?', 'Açık renk uzun kollu giymek', ['Şortla yürümek', 'Çıplak ayakla çimde yürümek', 'Koyu renk ve kısa kollu giymek'], 'Açık renk üzerinde keneler daha kolay fark edilir; paçaların çorapla kapatılması keneyi giysi içine ulaşmaktan alıkoyar.'),
  ('Kene ısırığından sonraki günlerde ısırık yerinde halka şeklinde yayılan kızarıklık ve ateş görülürse kişi ne yapmalıdır?', 'Sağlık kuruluşuna başvurmalıdır; Lyme olabilir', ['Yalnızca kaşınmayı beklemelidir', 'Isırık yerine tuz basmalıdır', 'Hiçbir şey yapmamalıdır'], 'Genişleyen halka şeklindeki kızarıklık (eritema migrans) Lyme hastalığının tipik belirtisidir; erken antibiyotik tedavisi etkilidir.'),
  ('İlkbaharda yabani sarımsak (ayı soğanı) yapraklarına benzeyen yaprakları nedeniyle zehirli bir bitkinin toplanması tehlikeli olabilir. Bu bitki hangisidir?', 'Güz çiğdemi', ['Papatya', 'Kuşburnu', 'Ihlamur'], 'Güz çiğdeminin ilkbahardaki yaprakları ayı soğanına benzer ve kolşisin içerir; yanlış yenirse ağır zehirlenme yapar. Bu nedenle yabani bitkilerde kesin teşhis gerekir.'),
  ('Yıldırımın düşmesi tehlikesi olan bir tepede yürüyen kişinin en güvenli kararı hangisidir?', 'Zirveden inip alçak yere gitmek', ['Zirvede çadır kurmak', 'Tek bir ağacın altına sığınmak', 'Metal baston ile yüksek yerde beklemek'], 'Yıldırım yüksek ve çıkıntılı noktalara düşme eğilimindedir; açık sırt, zirve, tek ağaç ve su kenarı en riskli yerlerdir.'),
  ('Şimşeği gördükten sonra gök gürültüsünü 30 saniyeden kısa sürede duyan bir doğaseverin izlemesi gereken "30-30 kuralı" ne öngörür?', 'Hemen korunup 30 dk beklemek', ['30 dakika yürümeye devam etmek', 'Şimşeğin renk değişimini 30 saniye izlemek', '30 dakika boyunca bir ağacın altında beklemek'], 'Gök gürültüsü 30 saniyeden önce geliyorsa fırtına yaklaşık 10 km içindedir ve tehlike yakındır; fırtına geçtikten sonra da 30 dakika beklenmelidir.'),
  ('Açık arazide yıldırımdan sığınabilecek bina ya da kapalı metal gövdeli araç yoksa en uygun duruş hangisidir?', 'Çömelip topuk birleştirmek', ['Yüzüstü yere yatmak', 'Ayakta durup kollarını açmak', 'Bir ağaca sarılmak'], 'Yere yatmak toprağa yayılan akımla temas yüzeyini artırır; ayakları birleşik çömelme, adım gerilimi riskini ve yıldırım çarpma yüzeyini azaltır. Yine de bu son çaredir.'),
  ('Yıldırım çarpmış bir kişiye dokunmak hakkında hangisi doğrudur?', 'Dokunmak güvenlidir; hemen ilk yardım yapılmalıdır', ['Dokunan kişi de çarpılır', 'Üç saat dokunulmamalıdır', 'Yalnızca lastik eldivenle dokunulmalıdır'], 'Yıldırım çarpan kişi yük taşımaz; kalp durması olasılığı yüksektir, bu yüzden hemen 112 aranmalı ve gerekiyorsa kalp masajı başlatılmalıdır.'),
  ('Fırtınada yıldırım riski karşısında bir grubun yürüyüş sırasında nasıl davranması önerilir?', 'Aralarında birkaç metre bırakarak dağılmak', ['Toplanıp tek bir noktada yan yana durmak', 'Ellerini birbirine tutuşturmak', 'Aynı ağacın altına toplanmak'], 'Grup dağılırsa yıldırım akımı zemin üzerinde yayılırken hepsini etkilemez; böylece biri yaralansa diğerleri yardım edebilir.'),
  ('Çadır içinde yıldırımdan korunmak için hangisi doğrudur?', 'Çadır korumaz; alçakta çömelinir', ['Çadır tam korur', 'Metal direk koruma sağlar', 'Uyku tulumu elektrik iletmez, tamamen koruma sağlar'], 'Kumaş çadır ve ince metal direkler yıldırımdan koruma sağlamaz; yüksek yerlerden ve ağaçlardan uzak, alçak bir yerde kamp kurmak gerekir.'),
  ('Dağlık bir vadide yürüyüşçü kamp yeri seçerken kuru bir dere yatağının kenarını seçmemelidir. Bunun asıl nedeni nedir?', 'Ani selin gelme ihtimali yüksektir', ['Dere yatağında rüzgâr hep çok sert eser', 'Kuru dere yatağında toprak çok serttir', 'Dere yatağı geceleri çok daha sıcak olur'], 'Dar ve eğimli vadilerde yağış başka yerde yağsa bile su dakikalar içinde yatağı doldurabilir; bu yüzden kamp yeri yüksek ve düz bir zeminde seçilir.'),
  ('Kamp sırasında derenin birden bulanıklaştığı, sürüklenen odun parçalarıyla gürlediği fark ediliyor. Doğru tepki hangisidir?', 'Hemen yüksek bir yere çıkmak', ['Çadırı dere kenarında bırakıp uyumak', 'Suyun kenarına eşya taşımaya devam etmek', 'Derede yüzmeye çalışarak diğer kıyıya geçmek'], 'Bulanıklaşma, ses ve sürüklenen odunlar ani selin yaklaştığını gösterir; derhal vadiden dik biçimde yüksek zemine tırmanılmalıdır.'),
  ('Dereden geçerken sırt çantasının bel ve göğüs kemerlerinin gevşetilmesi neden önerilir?', 'Düşünce çantayı kolayca bırakabilmek için', ['Çantanın daha rahat taşınması için', 'Çantanın içindeki eşyaların ıslanması için', 'Çanta ağırlığını artırarak dengeyi sağlamak için'], 'Su dolan çanta kişiyi suyun altına çekebilir; kemerlerin açık olması gerektiğinde çantayı hızla bırakmayı kolaylaştırır.'),
  ('Bir derenin iki ayrı kesitinden saniyede aynı hacimde (6 m³/s) su geçmektedir. Birinin enine kesiti 3 m², diğerinin 12 m² ise kesit alanı küçük olandaki ortalama akış hızı kaçtır?', '2 m/s', ['0,5 m/s', '18 m/s', '4 m/s'], 'Debi = alan × hız olduğundan v = 6 / 3 = 2 m/s bulunur; geniş kesitte hız 6 / 12 = 0,5 m/s\'dir. Bu nedenle geçit için genelde geniş ve sığ yer seçilir.'),
  ('Akıntıda geçerken yürüyüş sopası ve iki ayakla üç noktadan temas kurmanın amacı nedir?', 'Bir ayak kalkarken sağlam duruş sağlamak', ['Suyun derinliğini artırmak', 'Akıntının yönünü değiştirmek', 'Hızlı yüzmeyi sağlamak'], 'Üç noktada sabit durmak, akıntıya karşı bir ayağı yer değiştirirken düşme olasılığını azaltır; ağır akıntıda düşüşler yaralanmaya ya da sürüklenmeye yol açar.'),
  ('İrtifa arttıkça havadaki oksijen yüzdesi için hangisi doğrudur?', 'Yüzde 21 kalır, kısmi basınç düşer', ['Yüzde 21\'den yüzde 10\'a düşer', 'Yüzde 50\'ye çıkar', 'Sıfıra iner'], 'Atmosferin gaz oranları yaklaşık 100 km\'ye dek aynıdır; azalan, birim hacimdeki molekül sayısıdır ve akciğere alınan oksijen miktarıdır.'),
  ('Yüksek rakıma hızla çıkan bir kişide baş ağrısı, bulantı, yorgunluk ve uyku bozukluğu görülüyor. Bu tablo en çok hangisini düşündürür?', 'Akut dağ hastalığı', ['Sıcak çarpması', 'Zehirli mantar zehirlenmesi', 'Hipotermi'], 'Kısa sürede rakım artınca vücut aklimatize olamaz; baş ağrısı ve bulantı akut dağ hastalığının tipik belirtileridir ve genellikle 2500 m\'nin üzerinde görülür.'),
  ('Akut dağ hastalığı belirtileri kötüleşen bir tırmanıcı için en etkili müdahale nedir?', 'Daha alçak irtifaya inmek', ['Hızla zirveye çıkmaya devam etmek', 'Alkol tüketerek ısınmaya çalışmak', 'Bol yürüyüş yaparak adapte olmak'], 'İrtifa hastalığının asıl tedavisi alçalmaktır; belirtiler kötüleşirse akciğer ya da beyin ödemi gibi ağır tablolara ilerleyebilir.'),
  ('Yüksek irtifada akciğer ya da beyinde sıvı birikmesinden şüphelenilen bir kişi için doğru müdahale nedir?', 'Acilen alçalıp tıbbi yardım istemek', ['Hızla çıkışa devam etmek', 'Uyuyarak dinlenmek', 'Bol miktarda tuz yemek'], 'Yüksek irtifa akciğer ve beyin ödemi yaşamı tehdit eder; kesin tedavi alçalmak, oksijen vermek ve acil tıbbi yardıma ulaşmaktır.'),
  ('Dağda sisin bastırmasıyla yolunu kaybettiğini fark eden bir yürüyüşçünün ilk yapması gereken şey nedir?', 'Durmak, sakinleşmek ve durumu değerlendirmek', ['Hızla rastgele bir yöne koşmak', 'Haritayı atıp en yakın zirveye tırmanmak', 'Grubun ilerisine tek başına yürüyüp yol aramak'], 'STOP ilkesi (Stop, Think, Observe, Plan) panikle yanlış yöne gitmeyi engeller; yerinde durup konum, harita ve ortak bilgiler değerlendirilir.'),
  ('Kaybolan bir kişinin bulunmasını kolaylaştırmak için yürüyüşe çıkmadan önce yapılması gereken en önemli hazırlık hangisidir?', 'Güzergâhı ve dönüş saatini birine bildirmek', ['Güzergâhı kimseye söylememek', 'Hiç harita taşımamak', 'Telefonu evde bırakmak'], 'Plan bilinirse kayıp ihbarı hızla yapılır ve arama ekipleri nereye bakacaklarını bilir; bu da kurtarma süresini kısaltır.'),
  ('Telefonu çekmeyen bir bölgede kaybolan kişi, pil gücünü korumak için aşağıdakilerden hangisini yapmalıdır?', 'Uçak moduna alıp ekranı kısmak', ['Sürekli oyun oynamak', 'Parlaklığı sonuna kadar artırmak', 'Sürekli sinyal aramak için yürümek'], 'Sinyal ararken telefon en çok enerjiyi harcar; uçak modu ve düşük parlaklık pil ömrünü uzatarak acil durumda arama yapma şansını artırır.'),
  ('Açık alanda bir uçak ya da kurtarma helikopterine işaret vermek için aşağıdakilerden hangisi en etkili yöntemlerden biridir?', 'Ayna ile Güneş ışığını uçağa yansıtmak', ['Sessizce oturmak', 'Yeşil giysilerle yerde yatmak', 'Kayaların arkasına saklanmak'], 'Ayna yansıması çok uzaklardan fark edilir; yansıtılan ışık huzmesi uçağa yönlendirilir ve parlak flaş olarak görülür.'),
  ('Kurtarma ekibinin yukarıdan görmesi için yere işaret yaparken hangi özellik gereklidir?', 'Büyük, zıt renkli şekiller yapmak', ['Zeminle aynı renkte, küçük şekiller', 'Hiç şekil yapmamak', 'Sadece küçük taşlardan oluşan tek bir sıra'], 'Uzaklardan fark edilmesi için büyük ve çevreyle zıt renkte işaretler, örneğin karda koyu dallar, çimde açık renkli kumaş kullanılır.'),
  ('Doğada bir akarsudan alınan berrak, soğuk su neden yine de arıtılmadan içilmemelidir?', 'Giardia, bakteri ve virüs içerebilir', ['Berrak su hep çok soğuktur', 'Berrak su tatsızdır', 'Berrak su hep tuzludur'], 'Mikroplar gözle görülmez; hayvan dışkısı yukarıdaki kaynağı kirletmiş olabilir, bu yüzden kaynak suyu da arıtılmalıdır.'),
  ('Kamp sırasında içme suyunu güvenle arıtmanın en basit yollarından biri hangisidir?', 'Suyu kaynatmak', ['Suyu karıştırmak', 'Suyu dondurmak', 'Suyu güneşte bekletip bırakmak'], 'Kaynatma bakteri, virüs ve protozoaların çoğunu öldürür; yüksek rakımlarda kaynama noktası düştüğünden süre uzatılır.'),
  ('UV ile çalışan taşınabilir su arıtma cihazı hangi koşulda etkinliğini yitirir?', 'Su bulanık olduğunda', ['Su berrak olduğunda', 'Su çok soğuk olduğunda', 'Su tatlı olduğunda'], 'UV ışığı bulanık suda parçacıklar tarafından engellenir ve mikroplara ulaşamaz; bu yüzden berrak su gerekir.'),
  ('Kar ve buz eriterek içilecekse neden önce eritilip arıtılması önerilir?', 'Vücut ısısını düşürür, mikrop içerebilir', ['Kar suya dönüşmez', 'Kar çok tatlıdır', 'Kar yanar'], 'Karı doğrudan yemek vücut enerjisi harcar ve hipotermiye yol açabilir; kar ve buz da hayvan atıkları ya da toz içerebilir.'),
  ('Kamp ateşini terk etmeden önce ne yapılmalıdır?', 'Su dökmek ve korları yoklamak', ['Kendi hâline bırakmak', 'Üzerine kuru yaprak atmak', 'Üzerine toprak atmayıp hızlı uzaklaşmak'], 'Kor, görünür alev olmasa bile saatlerce parlayabilir; su dökme, karıştırma ve yeniden su dökme tüm korlar elle dokunulacak kadar soğuyana kadar sürdürülür.'),
  ('Çadır içinde kömürlü mangal ya da gazlı ocak kullanmak neden ölümcül olabilir?', 'Karbonmonoksit birikip zehirleyebilir', ['Çadır alev alıp çabucak yanar diye', 'Çadır içi çok ısınıp bunalttığı için', 'Çadır yağmurdan zarar görür diye'], 'Eksik yanmada karbonmonoksit oluşur; kapalı alanda birikerek kanda oksijenin yerini alır ve kişi fark etmeden bilincini kaybedebilir.'),
  ('Kamp ateşinden yanık yarası alan bir kişiye yapılacak doğru ilk müdahale hangisidir?', '10–20 dk akan serin suda tutmak', ['Yanığa doğrudan buz sürmek', 'Yanığa diş macunu sürmek', 'Kabarcıkları iğneyle patlatmak'], 'Serin akan su dokudaki ısıyı çeker ve hasarı azaltır; buz doku zedelenmesine yol açabilir, kabarcıkları patlatmak enfeksiyon riskini artırır.'),
  ('Çadır kurulacak yerin seçiminde aşağıdakilerden hangisine öncelik verilir?', 'Düz, kuru ve su akışından uzak bir zemin', ['Dere yatağına en yakın, en alçak çukur bir alan', 'Büyük, çürümüş bir ağacın hemen altındaki gölge', 'Rüzgârın doğrudan çarptığı açık bir sırt'], 'Çukur yerlerde yağmur suyu birikir, yaşlı ya da çürük ağaçlar dal düşürebilir; düz ve drenajı iyi zemin hem güvenli hem rahattır.'),
  ('Yürüyüşte terlemeyi önlemek için hangi ilke uygulanır?', 'Üşümeden giyip terlemeden çıkarmak', ['Giysileri gün boyu hiç değiştirmemek', 'Terlemeye başlayınca çok giysi eklemek', 'Terlemeyi artırmak için kalın mont giymek'], 'Terle ıslanan giysiler soğuyunca ısı kaybettirir; sıcaklık dengesini katmanları erkenden ayarlayarak korumak hipotermi riskini azaltır.'),
  ('Uzun bir yürüyüş öncesi yeni bir ayakkabının önceden kullanılması neden önerilir?', 'Ayağa alışıp kabarmayı azaltmak için', ['Ayakkabının rengini solması için', 'Ayakkabıyı kirletmek için', 'Ayakkabının ağırlığını artırmak için'], 'Sert ve alışılmamış ayakkabı sürtünmeyle kabarcık yapar; kısa yürüyüşlerle alıştırma, ayağın ve ayakkabının uyumunu sağlar.'),
  ('Naismith kuralına göre saatte 5 km yatay mesafe yürünür ve her 600 metrelik yükseliş için bir saat eklenir. Bu kurala göre 10 km uzunluğunda ve toplam 900 m yükselişi olan bir rotanın süresi yaklaşık ne kadardır?', '3,5 saat', ['2 saat', '4,5 saat', '5,5 saat yaklaşık'], 'Yatay 10 / 5 = 2 saat; yükseliş için 900 / 600 = 1,5 saat eklenir; toplam 3,5 saat bulunur.'),
  ('Bir grup 12 km\'lik bir parkuru saatte ortalama 3 km hızla yürüyecek. Moladan bağımsız yürüyüş süresi ne kadardır?', '4 saat', ['36 dakika', '3 saat', '9 saat'], 'Süre = yol / hız = 12 / 3 = 4 saattir; molalar ve zorlu bölümler için pay eklenmelidir.'),
  ('Grup yürüyüşünde yürüyüş hızı kime göre belirlenmelidir?', 'En yavaş yürüyen kişiye göre', ['En hızlı yürüyen kişiye göre', 'Rehberin kendi hızına göre', 'Rota boyunca değişen rastgele hızlara göre'], 'Grubun dağılmaması ve yorgun ya da yaralı üyelerin geride kalmaması için hız en yavaş kişiye göre ayarlanır; deneyimli bir kişi de grubun sonunda yürür.'),
  ('Yürüyüşe çıkarken sırt çantasının toplam ağırlığı için genel öneri nedir?', 'Vücut ağırlığının yaklaşık beşte biri', ['Vücut ağırlığının yarısı', 'Vücut ağırlığının iki katı', 'Ağırlık hiç önemli değildir'], 'Fazla yük yorgunluğu, sırt-bel zorlanmasını ve yaralanma riskini artırır; günübirlik yürüyüşte çanta genelde çok daha hafif tutulur.'),
  ('Dönüş saati (turn-around time) belirlemenin yürüyüşteki amacı nedir?', 'Gün ışığı bitmeden güvenle dönmek', ['Zirvede olabildiğince çok vakit geçirmek', 'Yemek saatini sabitlemek', 'Hava durumunu tahmin etmek'], 'Önceden belirlenen saat dolduğunda hedefe varılmasa bile dönüş, karanlıkta ve yorgun inme tehlikesini azaltır.'),
  ('Dağda iniş yaparken dizlerde ağrı ve yaralanma riskini azaltmak için hangi yöntem uygundur?', 'Yürüyüş sopası kullanıp adımları kısa tutmak', ['Mümkün olduğunca uzun adımlarla koşarak inmek', 'Dizleri kilitleyip düz bacakla ve hızlı inmek', 'Sırt çantasını tek omuza asarak ilerlemek'], 'İniş sırasında yük diz ve kalçaya biner; sopa kuvveti kollara dağıtır, kısa adımlar şokları azaltır ve dengeyi korur.'),
  ('Dolunaylı bir gecede yürüyüş planlayan biri hangi avantajı bekleyebilir?', 'Ay ışığı yolu seçilebilir kılabilir', ['Hava çok sıcak olur', 'Hayvanlar hiç görünmez', 'Ay ışığı pusula ibresini bozar'], 'Dolunayın yansıttığı ışık, bulutsuz gecede yol seçmeyi kolaylaştırır; yine de ormanda gölge ve engebeli zeminde fener gerekir.'),
  ('Gece yürüyüşünde kafa lambasının kırmızı moda alınması hangi koşulda en çok işe yarar?', 'Başkalarını rahatsız etmeden uyumu korumak', ['Çok uzağı aydınlatmak gerektiğinde', 'Yüksek hızla koşarken', 'Dere geçerken'], 'Kırmızı ışık gözbebeğini fazla küçültmez; harita okurken ve kamp ortamında uyum bozulmaz, yanında bulunanlar rahatsız olmaz.'),
  ('Patikanın bir bölümü çamurlu olduğunda en uygun davranış nedir?', 'Patikanın ortasından, çamurdan geçerek yürümek', ['Patika kenarındaki bitkilerin üstünden dolaşmak', 'Yeni bir yan yol açmak', 'Çamurlu yeri atlayıp kestirme tırmanmak'], 'Çevresinden dolanılırsa patika genişler ve bitki örtüsü ezilir; ortadan yürümek etki alanını dar tutar, çamur ayakkabıyla temizlenebilir.'),
  ('Muz ve portakal kabuğunu doğaya atmak neden sakıncalıdır?', 'Yavaş ayrışır, hayvanları insan yiyeceğine alıştırır', ['Hemen çürür ve toprağa karışarak yok olur, iz kalmaz', 'Toprağı verimli hâle getirip bitkilere katkı sağlar', 'Böcekleri uzaklaştırıp yürüyüş alanını temizler'], 'Doğal olmayan bölgelerde meyve kabukları aylarca kalabilir, hayvan beslenme düzenini değiştirir ve diğer ziyaretçiler için görsel kirliliktir.'),
  ('Yürüyüş sırasında dişi ve yavru geyiğe yiyecek ikram etmek neden önerilmez?', 'Hayvanlar insana bağımlı olur, saldırı riski artar', ['Hayvan zayıflar ve kış uykusuna erken yatar', 'Doğal besin zinciri güçlenir, hayvan sayısı artar', 'Geyikler yiyecek sevmediği için hiç ilgilenmez'], 'Beslenen hayvanlar doğal beslenmeyi bırakır, insandan korkmaz, yol kenarında trafik riski taşır ve ısırma olaylarına neden olabilir.'),
  ('Doğada tuvalet ihtiyacı için hangi kural uygulanır?', 'Sudan 60 m uzakta, 15–20 cm çukura', ['Su kenarında, dışkıyı suya yıkayarak', 'Patikanın hemen kenarında, taşla örtülerek', 'Çadırın arkasında, toprağa gömmeden bırakarak'], 'Dışkı su kaynaklarına bulaşıp hastalık taşıyabilir; küçük bir çukurda toprakla örtülürse daha hızlı ayrışır. Kâğıtlar çoğunlukla geri götürülür.'),
  ('Dere kenarında bulaşık ya da kişisel bakım yaparken sabun kullanılacaksa ne yapılmalıdır?', '60 m uzakta, atık suyu toprağa dağıtarak', ['Sabunlu suyu doğrudan dereye dökmek', 'Sabunu çadır yanına bırakmak', 'Suya hiç yaklaşmamak'], 'Biyolojik olarak ayrışan sabun bile sudaki canlılara zarar verebilir; atık suyu kaynaktan uzağa, toprağa yayarak dökmek suyun kirlenmesini önler.'),
  ('Boz ayı bölgesinde yürüyüş yapan biri ani bir karşılaşma riskini azaltmak için ne yapmalıdır?', 'Konuşarak ses çıkarmak', ['Sessiz ve hızlı yürümek', 'Yüksek sesli müzikle ilerlemek', 'Gece tek başına koşmak'], 'Ayılar ani karşılaşmalarda savunma amaçlı saldırabilir; ses çıkarmak onlara önceden uyarı verir ve kaçma fırsatı tanır.'),
  ('Kamp yapılan bölgede yaban hayvanlarını çekmemek için yemek hangi biçimde saklanmalıdır?', 'Kapalı kaplarda, çadırdan uzakta', ['Çadırın içinde uyku tulumunun yanında', 'Açıkta yerde', 'Dereye bırakılarak'], 'Hayvanlar kokuyla gelir; yemek ve kokulu eşyalar çadırdan uzakta ve sıkı kapalı saklanmalı, yemek de çadırdan uzakta pişirilmelidir.'),
  ('Yaban domuzu yavrularıyla birlikte olan bir dişiyle yakın mesafede karşılaşan biri ne yapmalıdır?', 'Yavaşça geri çekilip mesafe koymak', ['Yavrulara yaklaşıp onları uzaklaştırmak', 'Hayvana bağırıp üzerine yürümek', 'Taş fırlatıp domuzu uzaklaştırmak'], 'Anne yavrularını savunurken saldırgan olabilir; ani hareketler ve yavrulara yaklaşmak riski artırır, güvenli geri çekilme önerilir.'),
  ('Yaylalarda yürüyüşçüye doğru koşan çoban köpekleri ile karşılaşıldığında ne yapılması önerilir?', 'Yavaşça geri çekilip çobanı beklemek', ['Çok hızlı koşarak köpekten kaçmak', 'Sopa sallayarak köpeklere saldırmak', 'Köpeklere yiyecek atıp yatıştırmak'], 'Sürü köpekleri sürüsünü korur; kaçmak kovalamayı tetikler. Yavaş geri çekilmek ve çobanın müdahalesini beklemek riski azaltır.'),
  ('Yaban hayvanı fotoğrafı çekerken güvenli mesafenin kabaca ölçüsü hangisidir?', 'Kolu uzatıp başparmakla hayvanı kapatabilmek', ['Hayvanın gözlerini ayrıntılı seçebilmek', 'Hayvanın kokusunu rahatça alabilmek', 'Hayvana dokunup sevebilecek mesafede olmak'], 'Başparmakla hayvanı kapatabiliyorsanız genellikle yeterince uzaksınız demektir; uzun mercekle yakın görüntü almak hem sizi hem hayvanı korur.'),
  ('Sonbaharda üreme mevsiminde (kızgınlık) iri geyik erkeklerine yaklaşmak neden tehlikelidir?', 'Hormonlar yüzünden saldırganlaşırlar', ['Geyikler kış uykusuna yatar', 'Geyik boynuzları dökülmüştür', 'Geyik hızlı koşamaz'], 'Üreme dönemi erkeklerin saldırganlığını artırır; boynuzları ve ağırlıkları nedeniyle yaralanma riski ciddi olur, bu yüzden uzak durulmalıdır.'),
  ('Yaban hayvanı ya da sahipsiz köpek ısırdığında yaranın ilk müdahalesi nasıl yapılır?', '15 dk sabunlu suyla yıkayıp hekime gitmek', ['Yarayı ateşle dağlamak', 'Üstünü hiç temizlemeden kapatmak', 'Kendi hâline bırakıp beklemek'], 'Kuduz virüsü tükürükle bulaşır; yaranın uzun süre sabunlu suyla yıkanması virüs miktarını azaltır ve aşı-serum değerlendirmesi için hemen hekime gidilmelidir.'),
  ('Yürüyüşte tek başına bir kurt gören biri hakkında aşağıdakilerden hangisi doğrudur?', 'Genellikle kaçınırlar; sakin kalıp uzaklaşmak', ['Kurtlar insanları hep kovalar', 'Kurt sürüsü hep saldırır', 'Kurtlar yalnızca geceleri görülür'], 'Kurtlar insanlara karşı genellikle çekingendir; tehlike, kuduz gibi hastalıklı hayvanlar ya da beslenerek alışmış bireylerle sınırlıdır.'),
  ('Köpeğiyle yürüyüşe çıkan biri milli parkta tasmasız dolaşırsa ne olabilir?', 'Köpek hayvanları kovalar, hastalık bulaştırabilir', ['Köpek yaban hayatı için yararlı bir koruyucudur', 'Hayvanlar köpeğe yaklaşıp alışır', 'Tasmasız dolaşmak hiçbir sonuç doğurmaz'], 'Tasmasız köpek yuvaya ya da yavrulara zarar verebilir, yaban hayvanlarıyla çatışıp kene ya da hastalık taşıyabilir; bu yüzden tasma kuralı vardır.'),
  ('Boğulan bir kişiye yardıma çalışan sıradan biri için en güvenli sıralama hangisidir?', 'Seslenip uzatmak ya da şamandıra atmak', ['Hemen suya atlayıp boğulanı kucaklamaya çalışmak', 'Uzaktan izleyip yardım ekibinin gelmesini beklemek', 'Boğulanı sırtından çekip sürükleyerek getirmek'], 'Panik hâlindeki kişi kurtarıcıyı da batırabilir; uzatma ve atma yöntemleri (kamış, ip, şamandıra) kurtarıcıyı riske atmadan etkilidir.'),
  ('Kayalık kıyıda büyük bir dalganın birden insanları süpürmesi riskine karşı hangisi önerilir?', 'Denize sırtını dönmeyip kayalıklardan uzak durmak', ['Dalgalara sırt çevirip fotoğraf çekmek', 'Kayaların en alçak noktasında bekleyip dalgaları izlemek', 'Yüzerek kıyıdan uzaklaşıp dalgayı açıkta karşılamak'], 'Dalgalar sıralı gelmez; bazen dizilerin en büyüğü beklenmedik biçimde kıyıya ulaşır. Kaygan kayalıklardan uzak durmak ve denizi gözetmek korur.'),
  ('Denizde yüzerken ayağına kramp giren bir kişi için ilk önerilen davranış nedir?', 'Sakin kalıp sırtüstü yatmak, kası germek', ['Paniklenip çırpınarak kıyıya yüzmek', 'Hemen dibe dalıp ayağı kurtarmaya çalışmak', 'Kramp geçene kadar hızla yüzmeye devam etmek'], 'Panik enerjiyi tüketir; sırtüstü kalmak yüzmeyi kolaylaştırır, krampa giren kasın germe ve ovma ile gevşetilmesine zaman tanır.'),
  ('Denizanası değen bir yeri nasıl müdahale edilmesi önerilir?', 'Deniz suyuyla durulayıp ovmamak', ['Tatlı suyla hızla ovup kaşımak', 'Kuma sürterek yakıcı hücreleri uzaklaştırmak', 'Yaraya alkol dökerek dezenfekte etmek'], 'Tatlı su ve ovma, kalan yakıcı hücreleri tetikleyerek daha çok zehir salımına neden olabilir; deniz suyuyla yıkamak ve dokunaçları çıkarmak daha güvenlidir.'),
  ('Karadeniz kıyılarında yüzerken bayrak görünmese bile dalga ve akıntıyı kontrol etmek neden önemlidir?', 'Ani dalga ve akıntı kıyıdan uzaklaştırabilir', ['Su yaz boyunca aşırı sıcak olduğundan yüzme zordur', 'Karadeniz kıyılarında yüzmek her zaman yasaktır', 'Deniz yaz boyunca hiç dalgalanmaz, tehlike yoktur'], 'Dik inen kıyılarda ve rüzgârlı havalarda dalga kırılması ve akıntı yoğunlaşabilir, yüzücü yorulmadan sürüklenebilir.'),
  ('Rüzgârın karadan denize doğru estiği günlerde şişme deniz oyuncaklarıyla kıyıdan açılmak neden risklidir?', 'Rüzgâr oyuncakları kıyıdan uzağa sürükler', ['Rüzgâr denizi ısıtıp suyu tatlılaştırır', 'Rüzgâr dalgaları tamamen yok eder, deniz durgunlaşır', 'Rüzgâr oyuncakları her zaman kıyıya doğru iter'], 'Karadan denize esen rüzgâr hafif şişme cisimleri açığa taşır; sakin görünen kıyıda bile sürüklenme saatlerce fark edilmeyebilir.'),
  ('Mağaraya girerken neden her kişide en az üç bağımsız ışık kaynağı bulunması önerilir?', 'Işık arızalanırsa karanlıkta kalmamak için', ['Işıklar mağarayı süsleyip fotoğraf için ortam yaratır', 'Mağara hayvanları ışıktan korkup kaçsın diye', 'Işıklar mağara duvarlarını ısıtıp kurutsun diye'], 'Mağarada hiç doğal ışık yoktur; ışığın tamamen kesilmesi yolunu kaybetmeye ve ağır yaralanmaya yol açabilir, bu yüzden yedek ışıklar şarttır.'),
  ('Mağara içinde sıcaklık yıl boyu sabit ve düşüktür. Bu durum yürüyüşçü için ne tehlike doğurur?', 'Islak ve hareketsiz kalınırsa hipotermi riski', ['Aşırı sıcaktan sıcak çarpması riski', 'Güneş ışığından kaynaklanan güneş yanığı', 'Susuzluktan kaynaklanan solunum güçlüğü'], 'Mağaranın serin ve nemli hava kütlesi uzun süre kalındığında vücut ısısını düşürür; sıcak ve kuru yedek giysi gerekir.'),
  ('Kış uykusundaki yarasalara mağarada ışık tutmak ya da gürültü yapmak neden zararlıdır?', 'Uyanıp yağ enerjisini harcarlar, kışı atlatamayabilirler', ['Yarasalar hemen saldırıp insanları ısırır', 'Yarasaların bedeni parlayıp mağarayı aydınlatır', 'Yarasalar hızla büyüyüp mağaradan göç eder'], 'Kış uykusundaki yarasanın her uyanışı büyük enerji harcatır; birkaç kez rahatsız edilen birey bahara kadar yetecek yağı yitirebilir.'),
  ('Dik bir kaya yamacının altında yürürken en önemli güvenlik önlemi nedir?', 'Kask takıp tepedekilere dikkat etmek', ['Çok yüksek sesle konuşarak taşları durdurmak', 'Hızla koşarak yamacın altından kurtulmak', 'Sırt çantasını başın üzerine koyup yürümek'], 'Düşen taşlar çok hızlanır; kask baş yaralanmasını önler, üstte yürüyenler ise taş düşürürse "kaya!" diye bağırarak alttakileri uyarmalıdır.'),
  ('Don ve çözülme döngüsü kaya yüzeylerinde ne tür tehlike oluşturur?', 'Çatlakta donan su kayayı yarıp taş düşürebilir', ['Donan su kayayı sağlamlaştırıp birbirine yapıştırır', 'Don kayayı kayganlaştırıp yumuşatır, yürümeyi kolaylaştırır', 'Don ve çözülmenin kaya yüzeyine hiçbir etkisi olmaz'], 'Su donunca yaklaşık yüzde 9 genleşir ve çatlakları büyütür; çözülünce gevşeyen parçalar düşebilir.'),
  ('Yürüyüşte ayak bileği burkulan birine ilk 24-48 saat için hangi uygulama önerilir?', 'Dinlenme, soğuk, sıkıştırma ve yükseltme', ['Sıcak banyo yapıp bölgeyi masajla yoğurmak', 'Hızlı yürüyüşe devam ederek ısınmak', 'Bileği alkolle ovup güçlü sallamak'], 'İlk dönemde istirahat, soğuk, elastik bandajla sıkıştırma ve bacağı yükseltme şişmeyi azaltır; erken masaj ve ısı şişmeyi artırabilir.'),
  ('Dağda bir kırık şüphesi olan bacağa ilk müdahalede ne yapılır?', 'Hareket ettirmeden atelle sabitlemek', ['Bacağı çekip düzeltmeye çalışmak', 'Kişiyi yürüterek hastaneye ulaştırmak', 'Yara varsa yarayı ovup ısıtmak'], 'Kırık ucun hareketi damar-sinir hasarını artırır; atel, sopa ya da kıvrılmış mat ile sabitlemek ağrıyı azaltır ve yaralanmayı sınırlar.'),
  ('Orman yangınında ateşin yamaç yukarı daha hızlı yayılmasının temel nedeni nedir?', 'Alevler yakıtı önceden ısıtıp kurutur', ['Yokuşta oksijen azaldığından yanma yavaşlar', 'Yangın yukarı çıkarken soğur ve zayıflar', 'Yamaçlarda ağaçlar daha sıktır'], 'Yamaç yukarı eğimde alevler ve sıcak gazlar yakıta daha yakındır ve onu önceden ısıtır; bu nedenle yangın eğimle birlikte hızla ilerler.'),
  ('Çürümüş bir ağaç kütüğünün altını inceleyen gözlemci işini bitirdiğinde ne yapmalıdır?', 'Kütüğü eski konumuna dikkatle geri koymalı', ['Kütüğü başka bir yere atmalı', 'Altındaki toprağı kazıp düzeltmeli', 'Kütüğü kırıp hayvanları dışarı çıkarmalı'], 'Kütük altı nemli ve serin bir mikro habitattır; geri konmazsa orada yaşayan canlılar kurur, yuvaları ve gizlenme yerleri yok olur.'),
  ('Küçük böcek ve bitki yüzeylerini incelemek için el merceği (lup) kullanılırken doğru yöntem hangisidir?', 'Merceği göze yaklaştırıp nesneyi göze doğru yaklaştırmak', ['Merceği nesneye yapıştırıp gözü uzaklaştırmak', 'Merceği göze uzak tutup nesneyi merceğe çok yaklaştırmak', 'Merceği ters tutup uzaktan bakmak'], 'El merceği göze yakın tutulur ve nesne netleşinceye kadar yaklaştırılır; böylece görüş alanı geniş, görüntü keskin olur.'),
  ('Bir göletin yüzeyden dibe doğru farklı katmanlarında örnek almak neden gereklidir?', 'Işık, sıcaklık ve oksijen katmana göre değişir', ['Suyun bütün katmanları birbiriyle tamamen aynıdır', 'Yalnız yüzeyde yaşam bulunur, dipte canlı yoktur', 'Göl dibindeki çamur zehirli olduğundan örneklenmez'], 'Göletlerde yüzey ışıklı ve oksijenli, dip ise karanlık ve oksijen yönünden fakir olabilir; her katman farklı canlı topluluğu barındırır.'),
  ('Bir gölün berraklığını ölçmek için kullanılan beyaz-siyah disk (Secchi diski) nasıl kullanılır?', 'Diski indirip gözden kaybolduğu derinliği ölçmek', ['Diski suyun yüzeyinde yüzdürüp ışığını izlemek', 'Diski dipten yukarı çekip hızını ölçmek', 'Diski suda ısıtıp renk değişimine bakmak'], 'Diskin gözden kaybolduğu derinlik, suyun berraklığının (yani ışığın ne kadar derine indiğinin) göstergesidir.'),
  ('Bir gölün kıyısında yaklaşık 10\'ar kuşluk 12 gruba benzeyen bir sürü sayılıyor. Yaklaşık kaç kuş vardır?', 'Yaklaşık 120', ['Yaklaşık 22', 'Yaklaşık 10', 'Yaklaşık 1200'], 'Büyük sürülerde tek tek saymak yerine 10\'luk bloklar sayılır; 12 blok × 10 = yaklaşık 120 kuş eder.'),
  ('Kuş gözlemcisinin gün doğumundan sonraki ilk saatlerde saha çalışması yapmasının yararı nedir?', 'Kuşlar en aktif, ötüşler yoğun olur', ['Kuşlar sabahları hiç hareket etmeyip uyur', 'Gün çok sıcak olduğundan görüş zordur', 'Rüzgâr en şiddetli olduğundan sesler duyulmaz'], 'Sabah erken saatlerde kuşlar beslenme, öterek bölge belirtme ve hareketle en yoğun dönemdedir; gözlem ve işitme verimi artar.'),
  ('Kamera tuzağının rüzgârda sallanan otlar nedeniyle çok sayıda boş fotoğraf çekmesini azaltmak için ne yapılır?', 'Önündeki otları kesip hassasiyeti ayarlamak', ['Kamerayı yere gömerek rüzgârdan korumak', 'Kamerayı suya yaklaştırıp serinletmek', 'Kamerayı sürekli açık bırakıp lensini silmek'], 'Isıtılıp soğuyan bitkiler hareketle birlikte sensörü tetikleyebilir; önü açmak ve hassasiyeti düşürmek yanlış tetiklemeleri azaltır.'),
  ('İki belirgin tepeye aldığı azimutlardan haritada bulunduğu yeri belirlemek isteyen bir gözlemci bu yöntemde ne yapar?', 'Geri azimut çizgilerinin kesiştiği yer', ['İki tepenin tam ortasındaki nokta', 'Yalnızca yükseltiye bakarak bulunan nokta', 'Rüzgâr yönüne çizilen çizginin ucu'], 'Gözlemci her tepeden kendine doğru geri azimut çizgisi çizer; çizgilerin kesiştiği nokta konumdur (üçgenleme). Üçüncü bir tepe doğruluğu artırır.'),
  ('Sisli bir günde pusulayla düz bir hat izlemek için hangi yöntem önerilir?', 'Hat üzerinde görünür bir noktaya yürüyüp yenisini seçmek', ['Gözlerini kapatıp pusula iğnesini dinlemek', 'Yalnız pusulaya bakıp küçük adımlarla ilerlemek', 'Zikzaklı yürüyerek yönü sürekli değiştirmek'], 'Sisli havada yalnız pusula izlemek sapma yaratır; hat üzerindeki yakın bir hedefe yürümek ve tekrar nişan almak yönü korur.'),
  ('100 metreyi 65 çift adımla yürüyen bir kişi aynı adım uzunluğuyla 600 metre için kaç çift adım atar?', '390 çift adım', ['65 çift adım civarı', '130 çift adım civarı', '650 çift adım civarı'], '600/100 = 6 kat; 6 × 65 = 390 çift adım. Bu adım sayma (pace count) yöntemi sisli havada mesafeyi tahmin etmeyi sağlar.'),
  ('Harita üzerinde bir kamp alanı 400 m, zirve ise 1800 m yüksekliktedir. Zirveye tırmanışta toplam yükselti kazancı kaç metredir?', '1400 m', ['2200 m kadar', '1800 m kadar', '400 m kadar'], 'Yükselti kazancı 1800 − 400 = 1400 m\'dir; yürüyüş süresi hesabında bu değer Naismith kuralıyla kullanılır.'),
  ('Dünya üzerinde 0,5° enlem farkı yaklaşık kaç kilometreye karşılık gelir? (1° enlem yaklaşık 111 km)', 'Yaklaşık 55,5 km', ['Yaklaşık 111 km mesafe', 'Yaklaşık 5,5 km mesafe', 'Yaklaşık 222 km mesafe'], 'Enlem derecesi her yerde yaklaşık 111 km olduğundan 0,5 × 111 = 55,5 km bulunur. Boylam derecesi ise enleme göre değişir.'),
  ('40° kuzey enleminde 1° boylam farkı ekvatordakinden daha kısa bir mesafeye karşılık gelir. Yaklaşık değeri aşağıdakilerden hangisidir? (Ekvatorda 111,3 km, cos 40° ≈ 0,77)', 'Yaklaşık 85 km', ['Yaklaşık 111 km', 'Yaklaşık 143 km', 'Yaklaşık 40 km'], 'Boylam derecesi uzunluğu enlem kosinüsü ile azalır: 111,3 × cos 40° ≈ 85 km. Kutuplara gidildikçe meridyenler birbirine yaklaşır.'),
  ('Bir yürüyüşçü neden GPS cihazının yanı sıra kâğıt harita ve pusula da taşımalıdır?', 'Pil bitebilir, sinyal kaybolabilir', ['Kâğıt harita GPS\'ten daha doğru ölçüm verir', 'GPS çok ağır olduğu için kullanılmaz', 'GPS hiçbir koşulda çalışmaz'], 'Elektronik cihazlar pil, soğuk, su ve sinyal sorunlarından etkilenir; harita ve pusula bu tür arızalardan bağımsız bir yedek yön bulma yöntemidir.'),
  ('Güney Yarımküre\'de analog saatle yön bulmak için saat nasıl tutulur?', '12\'yi Güneş\'e çevirip akrep ile 12 arasındaki açıortaya bakmak', ['Akrebi Güneş\'e çevirip açıortayı güney saymak', 'Yelkovanı Güneş\'e çevirip ucuna bakmak', 'Saati ters çevirip akrebi kuzeye tutmak'], 'Güney Yarımküre\'de Güneş kuzeyde görülür; yöntem tersine döner: 12 işareti Güneş\'e bakar ve 12 ile akrep arasındaki açıortay kuzeyi verir.'),
  ('Orion\'un üç yıldızlı "kuşağı" gökyüzünde nasıl bir doğrultuda doğup batar?', 'Neredeyse tam doğudan doğup batıdan batar', ['Kuzeybatıdan doğar, güneydoğudan batar', 'Güneyden doğup kuzeyden batar', 'Başucundan geçip hiç batmaz'], 'Kuşak yıldızları gök ekvatoruna çok yakındır; gök ekvatoru üzerindeki cisimler yaklaşık tam doğudan doğup tam batıdan batar, bu yüzden yön bulmaya yarar.'),
  ('Meteor yağmuru izlemek için en iyi yöntem aşağıdakilerden hangisidir?', 'Karanlıkta yatıp geniş göğe bakmak', ['Dürbünle tek bir yıldıza odaklanmak', 'Işıklı şehir merkezinde gözlem yapmak', 'Teleskopla radyant noktasına bakmak'], 'Meteorlar gökyüzünün her yerinde belirebilir; dürbün ya da teleskop görüş alanını daraltır. Geniş bakış ve karanlığa uyum en iyi sonucu verir.'),
  ('Ay\'ın Dünya\'dan her zaman aynı yüzünün görünmesi neyi gösterir?', 'Dönme ve dolanma süreleri eşittir', ['Ay hiç dönmez, sürekli durur', 'İki yüzü birbirinin aynısıdır', 'Ay küresel değildir, yassıdır'], 'Ay\'ın kendi etrafındaki dönüşü ile Dünya çevresindeki turu aynı süreyi alır (eş zamanlı dönme); bu yüzden hep aynı yüz bize bakar.'),
  ('Güneş\'i doğrudan dürbün ya da teleskopla izlemek neden tehlikelidir?', 'Retinada kalıcı yanık yapıp körlük', ['Dürbünün merceğini ısıtıp eritme', 'Gözleri hafifçe kızartma ve sulandırma', 'Güneş görüntüsünü fazla küçültme'], 'Odaklanan Güneş ışığı retinada geri dönüşsüz hasar yapar; özel güneş filtresi ya da güneş gözlüğü (ISO 12312-2) olmadan Güneş\'e bakılmaz.'),
  ('Sisli bir günde hedefi bir dere kenarında olan bir yürüyüşçü, hedefin tam üstüne değil bilerek bir yanına nişan alıyor (aiming off). Bu yöntemin amacı nedir?', 'Bir yana sapıp yönü baştan bilmek', ['Hedefe hiç gitmeyip uzaklaşmak', 'Daima kuzeye yönelmek', 'Hedefi yüksek sesle çağırmak'], 'Hedefin tam üstüne nişan almak yerine bilinçli olarak bir yana sapmak, uzun doğrusal bir özellik (dere, yol) ile karşılaşınca hangi yöne gidileceğini netleştirir.'),
  ('Harita üzerinde kıvrımlı bir patikanın uzunluğunu ölçmenin pratik yolu nedir?', 'İp ile patika boyunca ölçüp ölçeğe çevirmek', ['Doğrudan çizgi ölçüp aynen kullanmak', 'Haritayı kıvırıp parmakla saymak', 'Yalnız iki uç noktaya bakmak'], 'Kıvrımlı yol, uç noktalar arasındaki doğrudan çizgiden uzundur; ip patikaya oturtulup gerilerek ölçülür ve harita ölçeğine göre gerçek uzunluğa çevrilir.'),
  ('Eş yükselti eğrileri kapalı bir halka biçiminde ise ve halkanın içine doğru yükselti artıyorsa bu hangi yer şeklini gösterir?', 'Tepe', ['Çukur', 'Vadi', 'Göl'], 'Merkeze doğru yükselti artıyorsa halka bir tepeyi gösterir; içine doğru azalıyorsa çukur ya da kapalı havzadır ve genellikle işaretlerle belirtilir.'),
  ('Güneş ışınları yüzeye 30° yükseklik açısıyla gelirken, 60° yükseklikle gelen aynı ışın demetine göre birim yüzeye düşen enerji yaklaşık kaç kat daha azdır?', 'Yaklaşık 1,7 kat', ['Yaklaşık 2 kat kadar', 'Yaklaşık 1,2 kat kadar', 'Yaklaşık 3 kat kadar'], 'Birim alana düşen enerji, Güneş\'in yüksekliğinin sinüsüyle orantılıdır: sin 60° / sin 30° = 0,866 / 0,5 ≈ 1,7. Kışın düşük açı bu yüzden yüzeyi daha az ısıtır.'),
  ('30 cm kalınlığında taze kar örtüsü yaklaşık kaç cm yağış suyuna denk gelir? (taze kar için yaklaşık 10:1 oranı alınız)', 'Yaklaşık 3 cm', ['Yaklaşık 30 cm', 'Yaklaşık 0,3 cm', 'Yaklaşık 10 cm'], 'Taze karın yoğunluğu suyun yaklaşık onda biri olduğundan 30 cm kar yaklaşık 3 cm (30 mm) su eşdeğeri verir; ıslak karda oran daha düşüktür.'),
  ('Okul bahçesinde fenoloji günlüğü tutan bir öğrenci için en uygun veri hangisidir?', 'Aynı ağaçta ilk tomurcuk, çiçek ve sararma tarihi', ['Tek bir gözlem yapıp fotoğrafını saklamak', 'Bahçedeki en güzel çiçeği çizmek', 'Yalnız o günün hava durumunu yazmak'], 'Fenolojik izleme, aynı bireylerde tekrarlanan tarih kayıtlarına dayanır; yıllar içinde karşılaştırma yapılabilmesi için tarih ve gözlem ölçütü sabit tutulur.'),
  ('Yaprak döken bir ağacın kışın yapraksız kalması hangi tehlikeyi azaltır?', 'Su kaybı ve kar yükünden kırılma', ['Ağacın ilkbahardaki büyümesi', 'Köklerin su alması', 'Çiçeklenme zamanı'], 'Yapraklar kışın donmuş toprakta su bulunamazken terlemeyle su kaybettirir ve kar yükünü artırır; yaprak dökümü bu iki riski düşürür.'),
  ('Kış mevsiminde yaprağı dökülmüş bir ağacı tanımak için hangisi daha güvenilir ipuçları sunar?', 'Kabuk deseni, dal dizilişi, tomurcuk biçimi', ['Yaprağın rengi ve yeşilliği', 'Meyvesinin tadı ve boyutu', 'Gölgesinin uzunluğu'], 'Yaprak olmadığında dal karşılıklı ya da almaşık dizilmesi, tomurcuk şekli ve kabuk yapısı türü ayırt eden başlıca özelliklerdir.'),
  ('Dumanın dik olarak yükseldiği, yaprakların kıpırdamadığı bir sakin havada Beaufort derecesi kaçtır?', '0 (tam sakin)', ['1 (hafif esinti)', '3 (hafif rüzgâr)', '6 (kuvvetli rüzgâr)'], 'Beaufort 0 tam sakin havadır: duman düz yükselir; 1\'de duman yönü rüzgârı gösterir ama flama kıpırdamaz.'),
  ('Büyük dalların oynadığı, telefon tellerinde ıslık duyulduğu ve şemsiye tutmanın güçleştiği bir rüzgâr yaklaşık hangi Beaufort kuvvetindedir?', '6', ['2', '9', '11'], 'Beaufort 6 (yaklaşık 39–49 km/s) kuvvetli rüzgârdır: büyük dallar sallanır, ıslık duyulur, şemsiye zor kullanılır.'),
  ('Sabah saatlerinde görülen küçük, kuleli altokümülüs bulutları öğleden sonra için neyi akla getirir?', 'Atmosfer kararsız; sağanak olasılığı artar', ['Havanın gün boyu çok açık ve durgun geçeceği', 'Sıcaklığın akşama doğru hızla düşeceği', 'Gece boyu sürekli çisenti yağacağı'], 'Kuleli altokümülüs, orta seviyede kararsızlığın işaretidir; gün içinde ısınmayla birlikte fırtına bulutlarına dönüşebilir.'),
  ('Alçaktaki bulutlar bir yöne, yüksekteki bulutlar başka bir yöne hareket ediyorsa bu nasıl yorumlanır?', 'Rüzgâr kayması var; hava değişebilir', ['Rüzgâr hiç esmiyor, hava sabit kalacak', 'Bulutlar sabit duruyor, hava değişmeyecek', 'Hava değişmeden uzun süre aynı kalır'], 'Rüzgârın yüksekliğe göre yön değiştirmesi (rüzgâr kayması), yaklaşan cephe ya da sistem değişikliğinin ipucu olabilir.'),
  ('Güneş ufka tam değiyormuş gibi görünürken gerçekte nerededir?', 'Kırılma nedeniyle ufkun biraz altındadır', ['Tam olarak ufuk çizgisinin üzerindedir', 'Ufkun çok yukarısında yükselmektedir', 'Gökyüzünde artık hiç görünmez'], 'Işık atmosferden geçerken kırılır ve Güneş yaklaşık kendi çapı kadar yüksekte görünür; diskin altı ufka değerken gerçekte disk ufkun altındadır.'),
  ('Sıcaklık ile çiy noktası arasındaki fark çok küçüldüğünde (örneğin 1–2 °C) hangi olayın oluşması olasıdır?', 'Sis ya da çiy oluşumu', ['Güneş yanığı riski artışı', 'Kuraklık ve kuru rüzgâr', 'Gökkuşağı belirmesi'], 'Çiy noktası, havanın doygunluğa ulaştığı sıcaklıktır; hava buna yaklaşınca su buharı yoğunlaşıp sis, bulut ya da çiy oluşturur.'),
  ('UV indeksi 8 ve üzerine çıktığında hangi uyarı yapılır?', 'Çok yüksek risk; öğle saatlerinde korunmalı', ['Güneş ışığı gerekli, önlem şart değil', 'Hiçbir önlem almaya gerek yok', 'Yalnızca geceleri risk vardır'], 'UV indeksi 8–10 arası çok yüksek risk anlamına gelir; birkaç dakikada yanık oluşabilir, bu yüzden güneş korumasına özen gösterilmelidir.'),
  ('Ağaç gövdesinde yerden yüksekte bırakılmış çamurlu sürtünme izleri neyi gösterebilir?', 'Hayvanın boyunu ve çamur banyosu yaptığını', ['Ağacın hastalık geçirdiğini ve kabuğunun döküldüğünü', 'Rüzgârın o yönden çok sert estiğini', 'Yağmurun ağacı yıkayıp çamurlandırdığını'], 'Yaban domuzu gibi hayvanlar çamurdan sonra gövdeye sürtünür; çamur izinin yüksekliği hayvanın boyuna kabaca fikir verir.'),
  ('Sonbaharda genç fidanların gövdesinde kabuğun dikey olarak soyulmuş ve dibinde kabuk parçaları görülmesi hangi hayvanın izi olabilir?', 'Kadife temizleyen bir erkek geyik', ['Ağaçta beslenen bir sincap', 'Gagasıyla vuran bir ağaçkakan kuşu', 'Yapraklarla beslenen bir salyangoz'], 'Geyik erkekleri üreme dönemi öncesi boynuzdaki kadifeyi temizlemek ve sürtünme ile işaret bırakmak için fidanlara boynuzunu sürter.'),
  ('Yaban hayvanının izini sürerken rüzgârın yönü neden önemlidir?', 'Rüzgâr yüze eserken koku hayvana gitmez', ['Rüzgâr hayvanın bıraktığı izleri tamamen siler', 'Rüzgâr sesin yayılmasını ve duyulmasını güçlendirir', 'Rüzgâr ışığı kırıp görüntüyü bulanıklaştırır'], 'Birçok memeli koku duyusu çok iyi gelişmiştir; rüzgâra karşı ilerlemek, kokunuzu hayvandan uzağa taşıyarak fark edilme olasılığını azaltır.'),
  ('Hayvan gözlemi için kurulan "hide" (gözlem kulübesi) neden etkili bir yöntemdir?', 'Gözlemciyi gizler, hayvanı rahatsız etmez', ['Hayvanı yiyecekle çağırıp yakalar', 'Hayvanın sesini kaydedip kaçırır', 'Hayvanları kafese alıp yakından izletir'], 'Kulübe gözlemcinin siluetini ve hareketini örter; hayvan insanı fark etmediğinden doğal davranır ve gözlem kalitesi artar.'),
  ('Bir iz fotoğrafı çekilirken ölçek açısından cetvelin iz yanına konulması neden önemlidir?', 'Gerçek boyutu sonradan belirlemek için', ['Fotoğrafı daha güzel göstermek için', 'İzi hayvandan gizlemek için', 'Cetvelin hayvanı çağırması için'], 'Ölçek olmayan fotoğrafta iz boyutu bilinemez; cetvel referans sağlayarak sonraki karşılaştırma ve tanımayı mümkün kılar.'),
  ('Bir doğa yürüyüşünde yere düşmüş, uçları kemirilmiş meşe palamutları görülürse bu iz hangi hayvana ait olabilir?', 'Küçük kemirgenler', ['Geyik gibi büyük otçullar', 'Kartal gibi yırtıcı kuşlar', 'Kurbağa gibi amfibiler'], 'Küçük kemirgenler palamut kabuğunu kemirerek içindeki çekirdeğe ulaşır; kabuk kenarlarında ince diş izleri kalır.'),
  ('Orman yolunda kırılmış, yarım yenmiş ve yere atılmış mısır koçanlarının bulunması hangi hayvanın varlığını düşündürür?', 'Yaban domuzu ya da benzer omnivor', ['Balık ve su kuşları', 'Yarasa ve gece kuşları', 'Dere kenarındaki su aygırı'], 'Yaban domuzu gibi hayvanlar tarla bitkilerine zarar verir; yarım bırakılan koçanlar ve toprak deşme izleri çoğu kez onlara aittir.'),
  ('Bir tavşan yuvası ile tilki yuvası arasında ayrım yaparken hangi ipucu işe yarar?', 'Tilki yuvası ağzında kemik ve tüy bulunur', ['Tavşan yuvası bir ağacın en tepe dalındadır', 'Tilki yuvası su içinde yapılır', 'İkisini ayırmanın hiçbir yolu yoktur'], 'Tilki yavrularını beslerken av artıklarını yuva ağzında bırakabilir; tavşan yuvasında böyle kalıntı olmaz.'),
  ('Karda barınak (kar mağarası) yapan kişi için havalandırma deliği neden gereklidir?', 'Karbondioksit birikimini önlemek için', ['Içeride ışığı artırıp kar erimesini hızlandırmak için', 'Barınağı serinletip nemi azaltmak için', 'Kar mağarasını rüzgârın içinden geçirmek için'], 'Kar mükemmel bir yalıtkandır ama kapalı hacimde karbondioksit birikip oksijen azalabilir; küçük bir delik havalandırma sağlar.'),
  ('Uyku tulumunun içine konulan sıcak su şişesi için hangi yerleşim daha yararlıdır?', 'Koltuk altı ve kasık yakınına', ['Ayakucundan uzak bir köşeye', 'Başın tam üstüne, tuluğun dışına', 'Yalnızca dizlerin arkasına'], 'Büyük damarların geçtiği bölgeler ısıyı hızla taşır; bu nedenle gövdeye yakın yerleştirilen sıcak şişe vücut sıcaklığını daha etkili artırır.'),
  ('Çölde gelen bir kum fırtınasında yürüyüşçü için hangi davranış önerilir?', 'Sırtını dönüp ağız-burnunu kapatmak', ['Rüzgâra karşı koşarak fırtınadan çıkmak', 'Gözleri tamamen açık tutup yürümek', 'Göğe bakıp yönünü korumak'], 'Kum taneleri göz ve solunum yollarını tahriş eder; bez, gözlük ve arkayı dönmek riski azaltır. Mümkünse sığınak bulunur ve fırtına geçene dek beklenir.'),
  ('Çölde aracı bozulan bir kişinin genellikle ilk tavsiye edilen davranışı nedir?', 'Araçta kalıp gölgeden yararlanmak', ['Hemen yürümeye başlayıp kasabaya ulaşmak', 'Aracı bırakıp geceleri yürümek', 'Aracı yakıp duman çıkarmak'], 'Araç kolay görülür, gölge ve su sağlar; çölde yürüyen kişi kısa sürede susuz kalıp bulunması zor hâle gelir.'),
  ('Yol kenarlarında yetişen sütleğen (Euphorbia) bitkisinin kırılınca akan beyaz sütü için hangisi doğrudur?', 'Deri ve gözleri tahriş eder', ['Besleyici olduğundan içilebilir', 'Yara iyileştirir, merhem gibi kullanılır', 'Tamamen zararsızdır, her yere sürülebilir'], 'Sütleğen türlerinin beyaz özsuyu yakıcı, tahriş edici maddeler içerir; deri ve göz teması ağrı ve iltihaba yol açabilir, bol suyla yıkanmalıdır.'),
  ('Arı sürüsünün saldırısına uğrayan biri için en doğru davranış hangisidir?', 'Yüzünü koruyup binaya sığınmak', ['Suya atlayıp arıların gitmesini beklemek', 'Yerde hareketsiz yatıp ölü taklidi yapmak', 'Arıları ellerle savurarak mücadele etmek'], 'Arılar hızla uzak mesafe takip edebilir; kapalı bir yere sığınmak en etkili korunmadır, suya atlamak da arıların beklemesi nedeniyle genellikle sonuç vermez.'),
  ('Güneş koruyucu ve böcek kovucu birlikte kullanılacaksa uygulama sırası nasıl olmalıdır?', 'Önce güneş kremi, sonra kovucu', ['Önce kovucu, sonra güneş kremi', 'İkisini bir kapta karıştırıp birlikte sürmek', 'Yalnızca birini seçmek, diğerinden kaçınmak'], 'Kovucu cilde yapışıp güneş kremi etkisini azaltabilir; krem emilince üzerine kovucu sürmek her ikisinin etkisini korur.'),
  ('Karlı dağda aşırı şiddetli kar fırtınasında görüşün sıfıra indiği "beyaz karanlık" (whiteout) durumunda en güvenli davranış nedir?', 'Olduğun yerde sığınıp hareket etmemek', ['Hızla yürüyerek görüşün açılmasına çalışmak', 'Yön bulmaya çalışarak yamaçtan inmek', 'Çantayı bırakıp koşmak'], 'Görüş yoksa yön ve zemin ayrıntıları algılanamaz; uçurum ve çığ riski yüksektir. Barınak yapıp beklemek ve ekibi bir arada tutmak en güvenlisidir.'),
  ('Berrak bir gölün kıyısından 1,5 m derinde görünen dip, gerçekte yaklaşık ne kadar derindir? (Suyun kırılma indisi yaklaşık 4/3)', 'Yaklaşık 2 m', ['Yaklaşık 1,5 m', 'Yaklaşık 1 m', 'Yaklaşık 3 m'], 'Işığın kırılması nedeniyle su olduğundan sığ görünür; gerçek derinlik görünen derinlik × n = 1,5 × 4/3 = 2 m bulunur.'),
  ('112 Acil Çağrı Merkezi\'ni arayan bir yürüyüşçü hangi bilgileri öncelikle vermelidir?', 'Konum, olay türü, yaralı durumu', ['Yalnızca adınızı ve telefon numaranızı', 'Yürüyüşe başlama saatini ve rotanın adını', 'Bulutların cinsini ve hava sıcaklığını'], 'Acil ekibin kısa sürede ulaşabilmesi için konum, kazanın niteliği ve yaralıların durumu gibi temel bilgiler verilmeli ve görevli yönlendirene kadar hat açık tutulmalıdır.'),
  ('Kamp sırasında kapalı çadırda yağmur sonrası içeride su birikmesinin önlenmesi için ne yapılır?', 'Su geçirmez taban örtüsü ve eğimli zemin', ['Çadırı çukur bir alana kurmak', 'Çadırı büyük bir ağacın altına kurmak', 'Çadır tabanını delip suyu akıtmak'], 'Taban örtüsü yer suyunu engeller; zemin eğimi suyu çadır dışına yönlendirir. Çukurlar su toplar ve çadır içi ıslanır.'),
  ('Yağmurlu havada çadır kumaşına iç yüzden dokunan kişi, dışarı doğru sızan nemden neden şikâyetçi olabilir?', 'İç nem soğuk kumaşta yoğunlaşır', ['Çadır kumaşı su emmez ve nemi geçirir', 'Yağmur kumaşı delerek içeri girer', 'İç hava aşırı kuru olduğundan nem çeker'], 'Çadır içinde solunum ve ter su buharı ekler; soğuk yüzeyde buhar yoğunlaşıp damlalara dönüşür. Havalandırma bu olayı azaltır.'),
  ('Yürüyüş ayakkabısı seçerken ayak bileğini kavrayan yüksek bilekli bot hangi arazi için daha uygundur?', 'Engebeli ve ağır yüklü arazi', ['Düz asfalt yol ve şehir içi yürüyüş', 'Sıcak kumsal ve plaj', 'Kapalı spor salonu'], 'Bilekli bot, bileği burkulmalara karşı destekler ve ayağı taşlardan korur; ağır yük ve engebede güvenlik sağlar.'),
  ('Gece kamp alanında her kişinin kafa lambasını çadırın ağzına bırakmasının amacı nedir?', 'Acil çıkışta ışığa hızla ulaşmak', ['Lambayı serinletip soğutmak', 'Işıkla hayvanları çekmek', 'Lambayı bulutlardan korumak'], 'Karanlıkta çadırdan çıkarken ya da acil durumda ışığa hızla ulaşmak güvenlik için önemlidir; böylece düşme ve yanlış yöne gitme riski azalır.'),
  ('Kuadratı araziye atarken gözlemcinin sırtını dönüp omzunun üzerinden atması hangi sorunu azaltmak içindir?', 'Bilinçli seçme yanlılığını', ['Kuadratın ağırlığının sebep olduğu yorgunluğu', 'Kuadratın kırılma ihtimalini', 'Kuadrat çizgilerinin eğrilmesini'], 'Gözle seçilen yerler genellikle daha çiçekli ya da ilginç olur; rastgele atma, temsil yeteneği yüksek örnekler almayı sağlar.'),
  ('Örnek sayısı 25\'ten 100\'e çıkarıldığında ortalamanın standart hatası yaklaşık nasıl değişir?', 'Yarıya iner', ['İki katına çıkar', 'Dörtte birine iner', 'Değişmez'], 'Standart hata, örnek sayısının karekökü ile ters orantılı azalır; örnek 4 katına çıkarsa hata 1/√4 = yarıya düşer.'),
  ('Beş ağaç gövdesinin çapı 3, 4, 4, 5 ve 40 cm ölçülmüştür. Uç değerin ortalamayı etkilediği bu veride tipik değeri en iyi hangi ölçü verir?', 'Medyan (4 cm)', ['Ortalama (11,2 cm)', 'En büyük değer (40 cm)', 'Aralık (37 cm)'], 'Ortalama 11,2 cm\'dir ama 40 cm\'lik uç değer onu şişirir; medyan 4 cm\'dir ve verinin tipik değerini daha iyi yansıtır.'),
  ('Bir deneyde gözlemcinin hangi grubun ölçüldüğünü bilmeden ölçüm yapması (kör ölçüm) hangi sorunu azaltır?', 'Gözlemci beklentisinin ölçüme sızması', ['Ölçü aletinin hassasiyetinin düşmesi', 'Hava koşullarının sürekli değişmesi', 'Örnek sayısının az olması'], 'Ölçüm yapan kişi beklediği sonucu bilirse bilinçsizce sonucu yanlı okuyabilir; kör ölçüm bu gözlemci yanlılığını düşürür.'),
  ('Bir öğrenci aynı deneyi tek bir fide ile yapıp sonuç çıkarıyor. Bu çalışmanın en büyük eksiği nedir?', 'Tek örnek var; sonuç tesadüf olabilir', ['Çok fazla veri toplanmış', 'Kontrol grubu gereğinden büyük', 'Sonuç aşırı net ve kesin'], 'Tek örnekle yapılan deney, rastlantısal farkları ayıramaz; birden çok tekrar, sonucun güvenilirliğini artırır.'),
  ('"Işıklı yerlerde yosunlar daha sık görülür" diyen bir öğrencinin bu fikri sınamak için ilk adımı ne olmalıdır?', 'Işığı ölçüp yosun örtüsünü iki yerde karşılaştırmak', ['Birkaç yosun toplayıp bir kavanoza koymak', 'Bu fikri deneme yapmadan doğru saymak', 'Yalnızca o günün hava durumuna bakmak'], 'Bir hipotezi sınamak için değişken ölçülmeli ve iki ya da daha çok koşulda sonuçlar karşılaştırılmalıdır; böylece ilişki veriyle desteklenir ya da çürütülür.'),
  ('Bilinmeyen bir bitkiyi sonradan tanımlamak için fotoğraf çekerken hangi görüntüler özellikle yararlıdır?', 'Yaprak üst ve alt yüzü, çiçek, gövde, habitat', ['Yalnızca uzaktan çekilmiş tek genel görüntü', 'Yalnızca toprağın rengini gösteren yakın plan', 'Gökyüzü ve bulut görüntüleri'], 'Tür ayırt eden özellikler yaprak dizilişi, çiçek yapısı, gövde ve yaşam alanıdır; bu yüzden çoklu açıdan fotoğraf, bitkiyi koparmadan sonradan tanımlamaya yardım eder.'),
  ('Bulut örtüsü "okta" birimiyle ifade edilir. Gökyüzünün yarısı bulutla kaplıysa bu kaç oktadır?', '4 okta', ['1 okta', '8 okta', '2 okta'], 'Okta, gökyüzünün sekizde birlik dilimleridir; yarı kapalı gökyüzü 4 oktaya, tamamen kapalı olan 8 oktaya denk gelir.'),
  ('Koordinatı 40,9° kuzey olarak verilen bir noktayı derece-dakika biçiminde yazarsak aşağıdakilerden hangisi doğrudur?', '40° 54\'', ['40° 9\'', '40° 90\'', '41° 0,9\''], 'Ondalık kısmı dakikaya çevirmek için 0,9 × 60 = 54 dakika bulunur; 40,9° = 40° 54\' eder.'),
  ('Hava günlüğünde ölçümlerin her gün aynı saatte yapılması neden önerilir?', 'Saat sıcaklık ve rüzgârı etkiler', ['Aletin daha hızlı ısınıp çalışması için', 'Hava durumunun gözlemciyi tanıması için', 'Saatin pil tasarrufu yapması için'], 'Sıcaklık gün içinde sürekli değişir; farklı saatlerdeki ölçümler günler arası farkı gerçek değişimden ayıramaz. Standart saat, karşılaştırmayı güvenilir kılar.'),
  ('Vatandaş bilimi platformlarında bir gözlemin tür adı yanlış girilmişse bu hata nasıl azaltılır?', 'Topluluk ve uzmanların doğrulamasıyla', ['Gözlemi silip yeniden girerek', 'Hiç kontrol edilmeden bırakılarak', 'Gözlemci kimliğini gizleyerek'], 'Çoğu platform, fotoğraflı gözlemlerin topluluk tarafından incelenmesine ve ortak onayla "araştırma kalitesine" yükselmesine dayanır; böylece yanlış tanılar düzeltilir.'),
  ('Bir araştırmacı bir türün hangi saatlerde etkin olduğunu belirlemek için gözlem planlıyor. En uygun örnekleme stratejisi hangisidir?', 'Gün boyu eşit aralıklı, aynı süreli gözlem', ['Yalnızca sabah saatlerinde gözlem', 'Yalnızca öğle saatinde gözlem', 'Hayvan görülene dek sürekli bekleme'], 'Saat örneklemesi, zamana yayılmış ve standart süreli olduğundan etkinlik örüntüsünü yansıtır; sadece sabah gözlemek akşam etkin türleri kaçırır.'),
  ('Aynı bir ağacı her ay fotoğraflayan öğrenci için aynı yerden, aynı açıyla çekmek neden önemlidir?', 'Değişimin ağaçtan geldiğini görmek', ['Fotoğrafın daha estetik görünmesi', 'Telefonun pilini tasarruf etmek', 'Ağacın daha küçük çıkmasını sağlamak'], 'Sabit nokta ve açı, dış etkenleri ortadan kaldırır; yaprak çıkışı ve renk değişimi gibi mevsimsel gelişimi güvenilir şekilde karşılaştırmayı sağlar.'),
  ('Bir çim alanda çiçek yüzdesini tahmin etmek için kuadrat kullanan öğrenci, "örtü yüzdesi"ni nasıl belirler?', 'Kapladığı alanı göz kararı yüzde olarak tahmin ederek', ['Çiçekleri tek tek sayıp toplayarak', 'Toprağı tartıp çiçeklerle oranlayarak', 'Kuadratı güneşe tutup gölgesini ölçerek'], 'Örtü yüzdesi, bitkinin kuadratın alanından ne kadarını kapladığıdır; sayılması zor olan otlarda bu yöntem sayıya göre daha pratiktir.'),
  ('Bir transekt boyunca her 5 m\'de bir kuadrat atılırsa 100 m\'lik hatta kaç kuadrat atılmış olur? (başlangıç ve bitiş noktaları dahil)', '21 kuadrat', ['20 kuadrat kadar', '19 kuadrat kadar', '25 kuadrat kadar'], 'Her 5 m\'de bir nokta, 0\'dan 100\'e kadar 20 aralık ve 21 nokta verir; bu yüzden toplam 21 kuadrat atılır.'),
  ('"Kutup Yıldızı, gökyüzünün en parlak yıldızıdır" yargısı için ne söylenebilir?', 'Yanlıştır; önemi sabit duruşundandır', ['Doğrudur, en parlak yıldızdır', 'Yalnız yaz mevsiminde doğrudur', 'Ay çıkmadığı zaman doğrudur'], 'Kutup Yıldızı gök kutbuna çok yakın olduğu için hemen hemen yerinde durur; ama parlaklığı en parlak yıldızlardan çok daha düşüktür.'),
  ('Güneş, Ay ve gezegenler gökyüzünde neden aynı dar şerit boyunca görülür?', 'Gezegen yörüngeleri aynı düzlemdedir', ['Tümü aynı çekim alanında kalmak zorundadır', 'Gökyüzü şerit biçiminde bir yapıdır', 'Gezegenlerin tümü aynı hızla döner'], 'Gezegen yörüngeleri hemen hemen aynı düzlemde olduğundan, Dünya\'dan bakıldığında hepsi ekliptik denen bir çizgi çevresinde dizilir.'),
  ('Bir yıldız bugün gece yarısı belirli bir noktada görülüyorsa ertesi gün aynı noktada yaklaşık kaç dakika erken görülür?', 'Yaklaşık 4 dakika', ['Yaklaşık 40 dakika', 'Yaklaşık 1 dakika', 'Tam aynı saatte'], 'Dünya Güneş çevresinde yılda yaklaşık 360° döner; bu, günde yaklaşık 1°\'ye, yani yaklaşık 4 dakikalık zaman farkına karşılık gelir.'),
  ('Güneş\'in en yüksekte olduğu yerel öğle anında, Kuzey Yarımküre\'de Türkiye\'de bir çubuğun gölgesi hangi yönü gösterir?', 'Kuzeyi', ['Güneyi', 'Doğuyu', 'Batıyı'], 'Öğle vakti Güneş güneyde en yüksek noktadadır; çubuğun gölgesi tam tersi yönde, yani kuzeye uzanır ve bu yüzden gölge pusula gibi kullanılır.'),
  ('Türkiye\'nin en batı ve en doğu noktaları arasındaki boylam farkı yaklaşık 18,5°\'dir. Bu iki nokta arasındaki yerel güneş zamanı farkı yaklaşık ne kadardır?', 'Yaklaşık 74 dakika', ['Yaklaşık 18 dakika kadar', 'Yaklaşık 3 saat kadar', 'Yaklaşık 10 dakika kadar'], 'Dünya bir derece boylamda 4 dakika döner; 18,5 × 4 = 74 dakika bulunur. Bu yüzden doğuda Güneş batıdakinden yaklaşık bir saat çeyrek önce doğar.'),
  ('Güneş ışığının Dünya\'ya ulaşması yaklaşık ne kadar sürer? (Güneş\'e uzaklık 150 milyon km, ışık hızı yaklaşık 300 000 km/s)', 'Yaklaşık 8 dakika', ['Yaklaşık 8 saniye', 'Yaklaşık 8 saat', 'Yaklaşık 1 gün'], '150 000 000 / 300 000 = 500 saniye, yani yaklaşık 8,3 dakika. Gözlediğimiz Güneş, bu yüzden 8 dakika öncesinin görüntüsüdür.'),
  ('Güneş\'in mart ekinoksunda gök ekvatorunu hangi yönde geçtiği söylenebilir?', 'Güneyden kuzeye', ['Kuzeyden güneye', 'Doğudan batıya', 'Hiç geçmez'], 'Mart ekinoksunda Güneş\'in deklinasyonu sıfırdan kuzeye doğru geçer; bu andan itibaren Kuzey Yarımküre\'de ilkbahar başlar ve gündüzler uzamaya devam eder.'),
  ('Güneş tutulmasını izleyen biri hangi gözlem yöntemine uymalıdır?', 'Tutulma gözlüğü ya da iğne deliğiyle', ['Çıplak gözle kısa süre bakmak', 'Normal güneş gözlüğüyle bakmak', 'Dürbünle doğrudan bakmak'], 'Tutulma sırasında bile Güneş\'in görünen kısmı retinaya zarar verir; ancak ISO 12312-2 gözlükler ya da projeksiyon güvenlidir.'),
  ('Kış boyunca kuş yemliği bulunduran bir kişinin yemliği düzenli olarak temizlemesi neden gerekir?', 'Hastalık yayılımını azaltmak için', ['Yemliğin daha çekici görünmesi için', 'Kuşların yemlikten uzaklaşması için', 'Tohumların daha lezzetli olması için'], 'Kalabalık yemliklerde dışkı ve nemli yem hastalık etmenlerini taşır; temizlik ve kuru yem, kuşlar arasında bulaşmayı sınırlar.'),
  ('Yaz öğle sıcağında hayvan gözlemi planlayan biri neden sabah erken ya da akşam saatlerini seçer?', 'Sıcakta gölgede dinlenip etkinliği azaltırlar', ['Hayvanlar öğleyin hep uyur, gece uyanmaz', 'Işık yalnız sabah saatlerinde bulunur', 'Akşam saatlerinde sıcaklık hep çok yükselir'], 'Sıcak saatlerde hayvanlar gölgeye çekilir ve görünür etkinlik azalır; sabah erken ve akşamüstü beslenme ve hareket yoğundur.'),
  ('Çadırın girişi hangi yöne bakmalıdır?', 'Rüzgârın tersine, sabah güneşine açık', ['Hâkim rüzgâra karşı, rüzgârı karşılayarak', 'Dere yatağına bakacak biçimde', 'Büyük ağacın altına dönük olarak'], 'Giriş rüzgâra dönükse yağmur ve soğuk içeri girer; rüzgâr almayan tarafa bakan, sabah güneşinden yararlanan girişte hem kurumak hem ısınmak kolaylaşır.'),
  ('Doğada drone ile hayvanlara yakın uçmak neden sakıncalıdır?', 'Hayvanı ürkütür, üremeyi aksatabilir', ['Hayvanlara iyi gelir, onları yakınlaştırır', 'Fotoğraf kalitesini azaltmaktan öteye zararı yoktur', 'Hayvanları çağırıp yuvadan uzaklaştırır'], 'Drone sesi ve gölgesi yırtıcıya benzediğinden kuş ve memelileri ürkütür; üreme alanlarında kaçışa ve yuva terkine yol açabilir.'),
  ('Yürüyüş sırasında yüksek sesle müzik dinlemek ve bağırmak hangi sorunları doğurur?', 'Yaban hayatını ürkütür, ziyaretçiyi rahatsız eder', ['Hayvanları yaklaştırıp güvenlerini artırır', 'Havayı ısıtıp yürüyüşü kolaylaştırır', 'Yolu kısaltıp yürüyüşü hızlandırır'], 'Doğal sessizliği bozmak, hayvanların kaçmasına ve diğer yürüyüşçülerin deneyimini bozmaya neden olur; bu nedenle ses düzeyi düşük tutulmalıdır.'),
  ('Dağ yürüyüşünde hızlı iniş sırasında bir yürüyüşçü düşüp başını çarptı, bilinci yerinde ama bulantı ve baş ağrısı var. Hangi tavır doğrudur?', 'İzleyip durum kötüleşirse 112\'yi aramak', ['Yürümeye devam ettirip hızlı inmesini sağlamak', 'Uyutup sabaha kadar yalnız bırakmak', 'Dinlenmesi için alkol vermek'], 'Baş darbesi sonrası kusma, bilinç değişimi ya da bulantı iç kanama göstergesi olabilir; kişi izlenmeli, tıbbi yardım istenmeli ve yalnız bırakılmamalıdır.'),
  ('Bir kişi yemek yerken boğazına bir parça kaçıp konuşamıyor ve nefes alamıyor. Yetişkinde uygulanacak ilk yardım nedir?', 'Heimlich: arkadan sarılıp karına bası', ['Su içirip beklemek', 'Sırta hafifçe vurup yürütmek', 'Yatırıp ayaklarını yukarı kaldırmak'], 'Tam tıkanıklıkta kişi konuşamaz; sırta vuruşlar ve Heimlich manevrası yabancı cismi çıkarmayı hedefler, çıkmazsa 112 aranır.'),
  ('Bir su kenarında, geniş bir kayaya tırmanmadan önce kayanın ıslak ve yosunlu olmasının yarattığı risk nedir?', 'Sürtünme azalır, kayma riski artar', ['Kaya daha sıcak olur ve ayak yanar', 'Kaya daha sert olur, tutunmak kolaylaşır', 'Kaya tamamen kurur ve sürtünme artar'], 'Yosun ve nem ayakkabı ile kaya arasındaki sürtünmeyi düşürür; ıslak kayalarda kayıp düşme çok yaygın bir yaralanma nedenidir.'),
  ('Dağda hava aniden bozulursa grup içinde hangi karar önerilir?', 'Korunaklı yere çekilip rotayı kısaltmak', ['Zirveye hızla çıkıp havanın düzelmesini beklemek', 'Yağmura aldırmadan aynı hızda yürümek', 'Gruptan ayrılıp herkesin tek başına inmesi'], 'Kötü hava hızla hipotermi, yıldırım ve kayıp riski doğurur; plan değiştirip dönmek ya da korunmak akılcıdır, zirve hedefi ikincil kalır.'),
  ('Gözlem formunda "güvenilirlik düzeyi" (emin ya da şüpheli) alanı bulunmasının yararı nedir?', 'Belirsizliği kaydedip sonradan değerlendirmeyi sağlar', ['Gözlemciyi sınav gibi sorguya çeker', 'Veriyi kısaltıp dosya boyutunu azaltır', 'Fotoğrafın ayrıntılarını değiştirir'], 'Her gözlem aynı kesinlikte değildir; belirsizliği belirtmek, sonradan veri analiz edenlerin hatalı kayıtları ayıklamasına yardım eder.'),
  ('Doğa günlüğü kaydının sonradan kolayca aranabilmesi için hangisi yardımcı olur?', 'Tarihleri aynı biçimde (yıl-ay-gün) yazmak', ['Her kaydı farklı bir biçimde yazmak', 'Tarih yazmamak, yalnız yer yazmak', 'Yalnızca resim çizip not eklememek'], 'Tutarlı biçim, sıralama ve arama işlemlerini kolaylaştırır; ISO tarih (yıl-ay-gün) bu açıdan en güvenli yazım biçimidir.'),
  ('Bilimsel gözlemde "yanlış negatif" hata ne demektir?', 'Tür oradayken görülmediği için yok sanılması', ['Olmayan bir türün oradaymış sanılması', 'Hava durumunun yanlış kaydedilmesi', 'Ölçeğin haritaya hatalı çizilmesi'], 'Gizli, sessiz ya da kısa süre görünen türler gözden kaçabilir; bu hata, "yok" sonucunun güvenilirliğini sınırlar ve tekrar gözlem gerektirir.'),
  ('Kuzey Kutbu\'nda yaz gündönümünde öğle (hep) Güneş ufkun kaç derece üzerinde görülür?', 'Yaklaşık 23,5°', ['Yaklaşık 66,5° kadar', 'Yaklaşık 90° kadar', 'Yaklaşık 0° kadar'], 'Kutup noktasında Güneş\'in yüksekliği deklinasyonuna eşittir; yaz gündönümünde deklinasyon 23,5° olduğundan Güneş gün boyu yaklaşık bu yükseklikte döner.'),
  ('Güneş\'in yüksekliği 26,5° olduğunda 1 metrelik dikey bir çubuğun gölgesi yaklaşık kaç metredir?', 'Yaklaşık 2 m', ['Yaklaşık 0,5 m', 'Yaklaşık 1 m', 'Yaklaşık 4 m'], 'Gölge = çubuk boyu / tan(yükseklik) = 1 / tan 26,5° ≈ 2 m eder; kış gündönümünde 40° enlemdeki gölgeler boyun iki katına yaklaşır.'),
  ('Ekvatorda Haziran gündönümünde öğle Güneş\'in yüksekliği yaklaşık kaç derecedir?', 'Yaklaşık 66,5°', ['Yaklaşık 90° kadar', 'Yaklaşık 23,5° kadar', 'Yaklaşık 0° kadar'], 'Ekvatorda yükseklik = 90° − |enlem − deklinasyon| = 90 − 23,5 = 66,5°\'dir; yılda iki kez ekinokslarda tam 90° olur.'),
  ('Kuş yuvası kutuları (yapay yuva) ne zaman yerleştirilir ve ne zaman temizlenir?', 'Üreme mevsiminden önce asılır, mevsim sonrası eski malzeme temizlenir', ['Üreme mevsimi ortasında kuluçka sırasında temizlenir', 'Yalnız yazın ortasında asılır', 'Hiç temizlenmez'], 'Yuva kutuları, kuşlar yuva yeri aramadan önce yerleştirilir; üreme bitince eski yuva malzemesi parazit ve hastalığı azaltmak için çıkarılır.'),
  ('Yürüyüşte duvar ya da ağaç oyuğundan çıkıp giren yoğun arı hareketi gören biri ne yapmalıdır?', 'Sessizce uzaklaşıp yetkililere ya da arıcıya haber vermek', ['Oyuğu kurcalamak', 'Duman sıkıp bakmak', 'Taş atarak arıları uzaklaştırmak'], 'Yoğun arı hareketi bir koloniyi gösterir; rahatsız edilen koloni savunmaya geçip çok sayıda sokma yaratabilir; yaklaşmak yerine uzak durmak ve bildirmek önerilir.'),
  ('Telefondaki kamera ile çekilen doğa fotoğrafında konum bilgisinin kaydedilmesi ne işe yarar?', 'Gözlemin nerede yapıldığını bilimsel veri olarak kullanılabilir kılar', ['Fotoğrafın boyutunu küçültür', 'Kameranın pilini artırır', 'Fotoğrafı güzelleştirir'], 'Konum, tarih ve saat gibi üstverilerle birlikte gözlem veri olarak harita üzerinde analiz edilebilir; hassas türlerde konum gizlenir.'),
  ('Dürbünün lenslerini temizlemek için en uygun sıra hangisidir?', 'Önce toz fırçayla ya da hava üfleyerek, sonra mikrofiber bezle silmek', ['Gömleğin ucuyla sert silmek', 'Tuzlu suyla yıkamak', 'Kâğıt havluyla ovmak'], 'Kuru tozu fırçalamadan silmek merceği çizebilir; önce parçacıklar uzaklaştırılır, ardından mikrofiber bez ve gerekirse lens temizleyici kullanılır.'),
  ('Kar örtüsünün gölün buz tutması üzerindeki etkisi için hangisi doğrudur?', 'Kar yalıtım yaparak buzun altta kalınlaşmasını yavaşlatır', ['Kar buzu hızla kalınlaştırır', 'Kar buzu eritir', 'Kar buzu hiç etkilemez'], 'Kar, havadaki soğuğun buza ulaşmasını azaltan bir yalıtım örtüsüdür; bu yüzden karlı buz, açık buza göre daha yavaş kalınlaşır ve zayıf olabilir.'),
  ('Bir yürüyüşçü Güneş\'in yönünü görmeden öğlen vakti 12:00 civarında gölgesine bakarak yön bulmak istiyor. Kuzey Yarımküre\'de Türkiye\'de doğru yaklaşım hangisidir?', 'Gölgenin uzandığı yön yaklaşık kuzeydir', ['Gölgenin uzandığı yön güneydir', 'Gölge doğuyu gösterir', 'Gölge batıyı gösterir'], 'Yerel öğle vaktinde Güneş en yüksekte ve güneydedir; kişinin gölgesi de karşı yönde, yani kuzeye düşer. Saat yaz-kış uygulamasına göre kayabilir.'),
  ('Sıcak bir yürüyüşte öğle arası yemeğinde tuzlu atıştırmalıklar yemek neden yararlıdır?', 'Terle kaybedilen tuzu geri kazandırır', ['Susuzluğu artırır', 'Vücut ısısını yükseltir', 'Mideyi boşaltır'], 'Terle sodyum ve diğer mineraller kaybedilir; tuzlu yiyecekler bu kaybı karşılar ve yalnızca su içmenin yol açabileceği sodyum düşüklüğünü önlemeye yardımcı olur.'),
  ('Yürüyüşte çatlayan ya da dökülen dudakları güneş ve rüzgârdan korumak için ne yapılmalıdır?', 'Güneş koruma faktörlü dudak balmı sürmek', ['Dudağı sık sık yalamak', 'Dudaklara tuz sürmek', 'Hiçbir önlem almamak'], 'Dudak derisi çok ince olduğundan UV ve rüzgârla kolay yanar; yalamak nemi buharlaştırarak kuruluğu artırır. Faktörlü balm hem güneşten hem rüzgârdan korur.'),
  ('Soğuk bir kamp gecesinde uyku tulumuna girmeden önce vücudu ısıtmak için kısa egzersiz yapmanın yararı nedir?', 'Kas ısısı artar ve tulumun içi daha hızlı ısınır', ['Terleyip giysileri ıslatmak', 'Vücudu yormak', 'Tulumu terletmek'], 'Hafif hareket vücut ısısını yükseltir; ancak terleme bırakılmamalı, çünkü ıslak giysi soğuk gecede hipotermi riskini artırır.'),
  ('Yürüyüş rotasında yağmur ve rüzgâr tahmini varsa en doğru plan hangisidir?', 'Rotayı kısaltmak ya da ertelemek, korunaklı alternatif yol hazırlamak', ['Hava ne olursa olsun planı aynen uygulamak', 'Hiç su almamak', 'Tek başına gitmek'], 'Kötü hava yürüyüşü zorlaştırır, riskleri artırır; planı hava durumuna göre esnek tutmak ve alternatif güzergâhı bilmek güvenliği artırır.'),
  ('Aynı mesafedeki iki patikadan biri 300 m, diğeri 800 m toplam yükselişe sahipse Naismith kuralına (600 m için 1 saat ekle) göre sürelerinin farkı ne olur?', 'Yaklaşık 50 dakika', ['Yaklaşık 5 dakika', 'Yaklaşık 3 saat', 'Fark olmaz'], 'Yükselişler arasındaki fark 500 m\'dir; 500 / 600 saat ≈ 50 dakikadır.'),
  ('Doğada sık görülen "dal kırılma sesi" ya da "çalı sallanması" ile ürken yürüyüşçü ne yapmalıdır?', 'Durup çevreye bakmak, sakin kalıp gerekirse ses çıkarıp hayvana varlığını bildirmek', ['Hemen koşmak', 'Sese doğru koşmak', 'Gözlerini kapatmak'], 'Ani ürkme genellikle bir hayvanın kaçma sesidir; ses çıkararak varlığınızı bildirmek ve sakin kalmak sürpriz karşılaşmaları azaltır.'),
  ('Kıyıda gelgit düzlüğünde yürürken suyun geri dönüşü hakkında en önemli güvenlik önlemi nedir?', 'Gelgit tablosunu önceden kontrol edip su dönmeden çıkmak', ['Hiç hesap yapmamak', 'Düzlüğe gece girmek', 'Suya doğru yürümek'], 'Gelgit düzlüklerinde su hızla yükselebilir ve yolu keser; gelgit saatleri önceden bilinmeli ve yeterli zaman kalırken çıkılmalıdır.'),
  ('Yürüyüş sonrası kene kontrolü sırasında hangi vücut bölgeleri özellikle dikkatle taranmalıdır?', 'Saçlı deri, kulak arkası, koltuk altı, kasık', ['Yalnızca avuç içi ve parmak araları', 'Yalnızca ayak tabanı ve topuk', 'Yalnızca omuz başı ve dirsek dışı'], 'Keneler ince, sıcak ve nemli deri kıvrımlarını tercih eder; bu bölgeler dikkatle taranmazsa kene günlerce fark edilmeden kalabilir.'),
  ('Dikenli yumurta biçimli kapsülleri ve büyük trompet çiçekleriyle ruderal alanlarda sık görülen, deliryuma yol açabilen zehirli bitki hangisidir?', 'Tatula', ['Kekik (Thymus), baharat bitkisi', 'Nane (Mentha), çay bitkisi', 'Adaçayı (Salvia), şifalı çay bitkisi'], 'Tatula, atropin ve skopolamin gibi tropan alkaloidleri taşır; zehirlenmede kalp çarpıntısı, halüsinasyon ve bilinç bulanıklığı görülür. Bu nedenle bitki hiçbir biçimde yenmemeli ve çocuklar uzak tutulmalıdır.'),
  ('Bir doğa meraklısı yeni gördüğü kuş türünü bilimsel olarak kaydetmek için hangi bilgiyi mutlaka eklemelidir?', 'Tarih, yer, habitat, sayı, davranış', ['Yalnızca fotoğrafın çözünürlüğü ve boyutu', 'Yalnızca o günkü hava sıcaklığı değeri', 'Yalnızca gözlemcinin yediği öğün'], 'Bir türün varlığını doğrulayan tarih-yer-habitat bilgisi, sayı ve davranış, kaydı bilimsel veri olarak yararlı kılar; diğer ayrıntılar ikincildir.'),
];
